(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0016.js"] = [{"id":"poem-6a5203864cee0f495a2ab952","title":"河满子·细雨裛开红杏","author":"杜安世","dynasty":"宋","verses":["细雨裛开红杏，新妆粉面鲜明。","东君何事交来早，更无绿叶同荣。","独倚青楼吟赏，目前无限轻盈。","命薄不依栏槛，或占郊坰。","清香繁艳真堪爱，枉教寂寞凋零。","相次牡丹芍药，王孙谁道多情。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-896","tags":[]},{"id":"poem-6a5404ec38073997de0805cd","title":"花舞·野客之名从此有","author":"史浩","dynasty":"宋","verses":["野客之名从此有。","多谢风流，飞驭陪尊酒。","持此一卮同劝后。","愿花长在人长寿。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-26","tags":[]},{"id":"poem-6a56ed5212ecd815c49f7be7","title":"毘陵东山","author":"李绅","dynasty":"唐","verses":["昔人别馆淹留处，卜筑东山学谢家。","业桂半空摧枳棘，曲池平尽隔烟霞。","重开渔浦连天月，更种春园满地花。","依旧秋风还寂莫，数行衰柳宿啼鸦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7d0ce467-1ee7-4612-979a-8c10c174357d","tags":[]},{"id":"poem-6a5d3d6e5d47952579966983","title":"玉簪花和希纯  其四","author":"刘跂","dynasty":"宋","verses":["凤尾成阴蕉叶重，金钿相对菊花繁。","莫悲举世无相识，佩蕙纫兰有屈原。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-7e7e4321-03d4-4fc3-a7d0-5715945f4442","tags":[]},{"id":"poem-6a5d9ab7b020f584bf8bc905","title":"感物","author":"司马光","dynasty":"宋","verses":["朝看新燕飞，暮聼子规啼。","尺蠖身藏叶，神龟尾曳泥。","鞲鹰何用掣，枥马不当嘶。","自伐憎狙巧，颓然忧木鸡。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-09463ae8-ee71-45cc-aa8b-217983f05184","tags":[]},{"id":"poem-6a5e81c1ffccbb0425322cd6","title":"题友人寓居","author":"唐求","dynasty":"唐","verses":["寓居无不在天涯，莫恨秦关道路赊。","缭绕城边山是蜀，弯环门外水名巴。","黄头卷席宾初散，白鼻嘶风日欲斜。","何处一声金磬发，古松南畔有僧家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-16a1792d-8510-4f93-9a39-984a2975787b","tags":[]},{"id":"poem-6a65478e05c2fcc36af84e19","title":"江雪","author":"柳宗元","dynasty":"唐","verses":["千山鸟飞绝，万迳人踪灭。","孤舟蓑笠翁，独钓寒江雪。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1f92134b-bca9-46eb-b2fe-87b30413041a","tags":["唐诗三百首","写雪","山水","冬天","雪","冬","写景","写鸟","五言绝句","鸟"]},{"id":"poem-6a667117bc45c51d738c4840","title":"依韵修睦上人山居十首 五","author":"李咸用","dynasty":"唐","verses":["春风春雨一何频，望极空江觉损神。","莺有来由重入谷，柳无情绪强依人。","汉庭谒者休言事，鲁国诸生莫问津。","赖是水乡樗栎贱，满炉红焰且相亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9ad8e520-0ef3-4eca-8a5c-5792a9133a72","tags":[]},{"id":"poem-6a690a90cdf970db1cc59b43","title":"偈颂十四首  其三","author":"释印肃","dynasty":"宋","verses":["若得桥行心亦行，莫教孤负见贫僧。","不因通济何如此，暗室千年忽遇灯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f7d99944-b4ea-4d3a-9529-439377d1a75c","tags":[]},{"id":"poem-6a6ff88e519d4ac5bd5f9066","title":"寄赵仁和","author":"释居简","dynasty":"宋","verses":["剧繁迎刃听裁剸，化自京师守令宣。","处默有声长殷殷，所闻无善不拳拳。","戚联阊阖天虽近，下若沧溟德更渊。","任是灵椿根力浅，也应凡草不齐年。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d8a04059-1947-4c87-9775-52f99114ee0f","tags":[]},{"id":"poem-6a7654a75d84df9d78847d6d","title":"将发","author":"李贺","dynasty":"唐","verses":["东床卷席罢，[濩]落将行去。","秋白遥遥空，日满门前路。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b0059347-876b-42c8-b167-f5087c5c7f34","tags":[]},{"id":"poem-6a7b4f9f21bc9518dadf8bea","title":"和李侍御萼岁初夜集处士书阁","author":"皎然","dynasty":"唐","verses":["迟贤心置阁，高意此郊居。","古径行春早，新窗见月初。","放歌还倚瑟，讲道亦观书。","为我留禅位，来逢此会疎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-7e11e0e1-e387-49ca-82ca-9192b10275ba","tags":[]},{"id":"poem-6a82d327c3474b095f3ad225","title":"浣溪沙·惆怅梦余山月斜","author":"韦庄","dynasty":"五代","verses":["惆怅梦余山月斜，孤灯照壁背窗纱，小楼高阁谢娘家。","暗想玉容何所似，一枝春雪冻梅花，满身香雾簇朝霞。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-30","tags":[]},{"id":"poem-6a846ee5462d4df49923da56","title":"花枕","author":"杨凝","dynasty":"唐","verses":["席上沈香枕，楼中荡子妻。","那堪一夜里，长湿两行啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-01bcddd1-4f13-4740-9e1f-d2c510188ab7","tags":[]},{"id":"poem-6a852df3c4978f011b5358a2","title":"春秋战国门 秦武阳","author":"周昙","dynasty":"唐","verses":["丱岁徒闻有壮名，及令为副误荆卿。","是时环柱能相副，谁谓燕囚事不成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3f7bc94f-538a-43ad-aaca-22aac3e769be","tags":[]},{"id":"poem-6a8a00869bcac39fe3b51840","title":"采葛","author":"佚名","dynasty":"先秦","verses":["彼采葛兮，一日不见，如三月兮！","彼采萧兮，一日不见，如三秋兮！","彼采艾兮！一日不见，如三岁兮！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-71","tags":[]},{"id":"poem-6a8c1e3e084dd53b577b1888","title":"江行无题一百首 二十九","author":"钱珝","dynasty":"唐","verses":["行到楚江岸，苍茫人正迷。","秪如秦塞远，格磔鹧鸪啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-99b162d3-33b4-41d0-9f0f-3a555bf5b8e4","tags":[]},{"id":"poem-6a90a609903a23259fc79eb1","title":"菩萨蛮·洛阳城里春光好","author":"韦庄","dynasty":"五代","verses":["洛阳城里春光好，洛阳才子他乡老。","柳暗魏王堤，此时心转迷。","桃花春水绿，水上鸳鸯浴。","凝恨对残晖，忆君君不知。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-37","tags":[]},{"id":"poem-6a9c77bc978c5fba36696e53","title":"吊李元宾坟","author":"孟郊","dynasty":"唐","verses":["晓上荒凉原，吊彼寂寥魂。","眼咽此时泪，耳凄在日言。","冥冥千万年，坟锁孤松根。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-f07e39fe-5dd8-4940-a589-07af5f2db4ec","tags":[]},{"id":"poem-6a9e153b4344b1a3f82f141c","title":"郊庙歌辞 释奠武成王乐章 亚献终献","author":"于邵","dynasty":"唐","verses":["贰觞以献，三变其终。","顾此非馨，尚达斯衷。","茅缩可致，神歆载融。","始神翊周，拯溺除凶。","时维降祐，永绝兴戎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-12ec2d0d-8a04-46d8-873b-b3ed0b88b4d8","tags":[]},{"id":"poem-6a9fda5d26ed706257acbce8","title":"再和  其一","author":"张栻","dynasty":"宋","verses":["闭门谢客少过从，独倚修篁傲碧空。","忽喜千条发琼蕊，纷如万鹤出樊笼。","与君前日徘徊久，得句悬知惨淡中。","胸次本无愁可著，何为苦要酒兵攻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-42251b17-b0a9-4a89-a53b-3ee30be56785","tags":[]},{"id":"poem-6aa1e9a15b5656ba71f43d2e","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["大凡事是姻缘，我孩儿莫忧煎。","侯门相府知有万千，读书人怕没为姻眷，料它每福缘浅。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2639","tags":[]},{"id":"poem-6ab0ec567ab8ba4dcc82e9d0","title":"上之回","author":"沈佺期","dynasty":"唐","verses":["制书下关右，天子问回中。","坛𫮃经过远，威仪侍从雄。","黄麾摇昼日，青幰曳松风。","回望甘泉道，龙山隐汉宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-1f8bdfa2-20aa-45a4-a460-77df1ebab288","tags":[]},{"id":"poem-6ab2f67d38ce36bffdc22d58","title":"采桑子·林间摘遍双双叶","author":"晏殊","dynasty":"宋","verses":["林间摘遍双双叶，寄与相思。","朱槿开时。","尚有山榴一两枝。","荷花欲绽金莲子，半落红衣。","晚雨微微。","待得空梁宿燕归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-468","tags":[]},{"id":"poem-6ab97add93505f359abd5953","title":"浣溪沙·谁道飘零不可怜","author":"纳兰性德","dynasty":"清","verses":["西郊冯氏园看海棠，因忆《香严词》有感。","谁道飘零不可怜，旧游时节好花天。","断肠人去自经年。","一片晕红才著雨，几丝柔绿乍和烟。","倩魂销尽夕阳前。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-103","tags":[]},{"id":"poem-6ac35a0dc1b008ab65a8bb05","title":"春日书怀","author":"赵嘏","dynasty":"唐","verses":["暖莺春日舌难穷，枕上愁生晓听中。","应褭绿窗残梦断，杏园零落满枝风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-27c25ad5-91a1-49fe-95e2-4dc5c14eb09c","tags":[]},{"id":"poem-6ac988ee9feb4226272a570c","title":"别离怨","author":"郑遂初","dynasty":"唐","verses":["荡子戍辽东，连年信不通。","尘生锦步障，花送玉屏风。","只怨红颜改，宁辞玉簟空。","系书春雁足，早晚到云中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-76089241-9c53-4d9d-9fdb-1bc79448b878","tags":[]},{"id":"poem-6aca4ccd0fae96cff5050494","title":"浪淘沙·红影湿幽窗","author":"纳兰性德","dynasty":"清","verses":["红影湿幽窗，瘦尽春光。","雨余花外却斜阳。","谁见薄衫低髻子，抱膝思量。","莫道不凄凉，早近持觞。","暗思何事断人肠。","曾是向他春梦里，瞥遇回廊。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-104","tags":[]},{"id":"poem-6ad11ddef1c4dc74ad98d5aa","title":"浣溪沙·握手河桥柳似金","author":"薛昭蕴","dynasty":"五代","verses":["握手河桥柳似金，蜂须轻惹百花心，蕙风兰思寄清琴。","意满便同春水满，情深还似酒杯深，楚烟湘月两沉沉。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-29","tags":[]},{"id":"poem-6ad2ef1723a55cfb3b1c98df","title":"得信酬回","author":"佚名","dynasty":"唐","verses":["人回忽得信，具委书中情。","覊思顿虽豁，忆君心转盈。","自怜飘泊者，邂逅闭荒城。","欲识肝肠断，更深听叫声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2dc60e5c-6dbc-43bc-9dd6-528ab3a212f7","tags":[]},{"id":"poem-6ad5299249521506c3a71752","title":"兵要望江南 医方第二十九（十六首） 九","author":"易静","dynasty":"唐","verses":["金疮法，闲时备急方。","五月五日平明节，采其诸草捣成浆，石灰共作汤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4580e857-17d3-4c58-a726-b3b5532b69c4","tags":[]},{"id":"poem-6ad629f86ebe3b72103ca916","title":"章华台  其二","author":"李纲","dynasty":"宋","verses":["章华夜饮晓从糜，翠被天寒雨雪霏。","马足车尘竟何往，空令子革诵招祈。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-ba52c005-e660-4eee-8c0d-6d72c29df8b0","tags":[]},{"id":"poem-6ada37cc654fb563b544aa02","title":"梦二叔","author":"王十朋","dynasty":"宋","verses":["二叔年皆八十余，经年不见久无书。","江山不隔还乡梦，昨夜迢迢到佛庐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-87849cc3-455c-47a8-89be-665718913255","tags":[]},{"id":"poem-6ae3aade41e0b9e0dc9716a1","title":"省题诗二十一首 晓日禁林闻清漏","author":"王棨","dynasty":"唐","verses":["晓过宫垣侧，犹闻漏水频。","清音传五夜，山影值三春。","露碎金壶滴，风和玉佩振。","依稀连鳯沼，髣髴辨鸡人。","温树初凝雾，彤闱渐向晨。","若非鸳鹭伴，谁此继香尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4d724b13-091d-4c81-baeb-caeac0182cca","tags":[]},{"id":"poem-6ae434673514b8aa92f322c2","title":"寓居临平山下三首 其一","author":"张祜","dynasty":"唐","verses":["三月平湖浪（《大典》及《临平记》作「草」。","）欲齐，绿杨分映（《临平记》作「影」。","）入长堤。","田家起处乌龙（《临平记》作「犹」。","）静，（《大典》及《临平记》作「吠」。","）酒客醒时谢豹啼。","溪（《大典》及《临平记》作「山」）槛正当莲叶渚，水泾新麦稻苗畦。","（《大典》作「水堘新擘稻秧畦」，《临平记》作「水塍新筑稻秧畦」。","）人间谩说多歧路，咫尺神仙洞却迷。","（《临平记》作「路欲迷」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-28e5fe53-7997-4d0c-b998-4d908628d46d","tags":[]},{"id":"poem-6ae7e1ab671a69be68680d06","title":"菩萨蛮·白日惊飚冬已半","author":"纳兰性德","dynasty":"清","verses":["白日惊飚冬已半，解鞍正值昏鸦乱。","冰合大河流，茫茫一片愁。","烧痕空极望，鼓角高城上。","明日近长安，客心愁未阑。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-176","tags":[]},{"id":"poem-6ae8c65f38177cd3863735e6","title":"和定国湖上  其二","author":"刘跂","dynasty":"宋","verses":["雨过松篁多样翠，风回苹藻一般香。","玉兰桃李非无意，兴味由来静处长。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-a65eae47-12aa-4d4f-a369-483e6a6c7d09","tags":[]},{"id":"poem-6af015a29052d5972009c0ac","title":"古意九首 一","author":"贯休","dynasty":"唐","verses":["一雨火云尽，闭门心冥冥。","兰花与芙蓉，满院同芳馨。","佳人天一涯，好鸟何嘤嘤。","我有双白璧，不羡于虞卿。","我有径寸珠，别是天地精。","玩之室生白，潇洒身安轻。","只应天上人，见我双眼明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-309461b0-8cf8-4288-8eca-6f610fa9d2ec","tags":[]},{"id":"poem-6af3f2573e7aa7eb201e4265","title":"献从兄","author":"张籍","dynasty":"唐","verses":["悠悠旱天云，不远如飞尘。","贤达失其所，沉飘同众人。","擢秀登王畿，出为良使宾。","名高满朝野，幼贱谁不闻。","一朝遇谗邪，流窜八九春。","诏书近迁移，组绶未及身。","冬井无寒冰，玉润难为焚。","虚怀日迢遥，荣辱常保纯。","我念出游时，勿吟康乐文。","愿言灵溪期，聊欲相依因。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c31c213f-6a36-4e49-b027-ba2f54bdb95e","tags":[]},{"id":"poem-6af9038ebee20a9f76393fbe","title":"二月望日","author":"徐凝","dynasty":"唐","verses":["长短一年相似夜，中秋未必胜中春。","不寒不暖看明月，况是从来少睡人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1edd4936-c8a8-4a6c-893e-49d9d43db7bf","tags":[]},{"id":"poem-6afc54df5883c61a0fa8e79b","title":"句","author":"宋太祖","dynasty":"宋","verses":["未离海底千山黑，才到天中万国明。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-adaa27a4-389b-48ca-8021-80f0471433c4","tags":[]},{"id":"poem-6b0353ba4316b772ca643d56","title":"和梁签判颍州西湖十三题 碧澜堂","author":"苏颂","dynasty":"宋","verses":["北渚清泠十顷波，偶来凭槛意如何。","且观秋水蒙庄论，休听沧浪渔父歌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-7b6eb166-9fe4-4b23-a719-077a31f2bb10","tags":["西湖"]},{"id":"poem-6b186a1cb9b2dddad398df8f","title":"柳枝词十首  其六","author":"徐铉","dynasty":"宋","verses":["风暖云开晚照明，翠条深映凤皇城。","人间欲识灵和态，听取新词玉管声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-9960ec03-98c0-43da-a756-91ead6dd32fb","tags":[]},{"id":"poem-6b19f4781ac43799fce1d655","title":"鱼山神女祠歌 送神","author":"王维","dynasty":"唐","verses":["纷进舞兮堂前，目眷眷兮琼筵。","来不言兮意不传，作暮雨兮愁空山。","悲急管兮思繁弦，神之驾兮俨欲旋。","倏云收兮雨歇，山青青兮水潺湲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-dfc946ec-a63e-44c4-82f8-09b02cc23ea0","tags":[]},{"id":"poem-6b1b719c49111a22abe5e443","title":"寄远","author":"赵嘏","dynasty":"唐","verses":["禁钟声尽见栖禽，关塞迢迢故国心。","无限春愁莫相问，落花流水洞房深。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a06be1d4-e9d9-4e50-9447-adc4118c8b68","tags":[]},{"id":"poem-6b23b67a6cbadce30d1cbf63","title":"奉和舍人叔直省时思琴","author":"张籍","dynasty":"唐","verses":["蔼蔼紫薇直，秋意深无穷。","滴沥仙阁漏，肃穆禁池风。","竹月泛凉影，萱露澹幽丛。","地清物态胜，宵闲琴思通。","时属雅音际，逈凝虚抱中。","达人掌枢近，常与隐默同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d462022f-de0f-450b-9410-3dacca1f1d4d","tags":[]},{"id":"poem-6b27b34dace7d9deb2a604fc","title":"清平乐·杏花时候","author":"毛滂","dynasty":"宋","verses":["杏花时候。","庭下双梅瘦。","天上流霞凝碧袖。","起舞与君为寿。","两桥风月同来。","东堂且没尘埃。","烟艇何时重理，更凭风月相催。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-718","tags":[]},{"id":"poem-6b2afc0a09631e6fad18a70c","title":"李化文书堂","author":"陈岩","dynasty":"宋","verses":["世路嵚崎两鬓丝，山中留客且伸眉。","竹林胜践虽相似，犹恨前贤所欠诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-2a2ee969-1f81-4083-b6a2-e94aa8591f2c","tags":[]},{"id":"poem-6b2cc824dc9eeb71575375b2","title":"满庭芳·乡物牵情","author":"晁补之","dynasty":"宋","verses":["乡物牵情，家山回首，浩然归兴难收。","报恩心事，投老拼悠悠。","却笑当年牛下，轻自许、激烈寒讴。","成何事，夷犹桂楫，兰芷咏芳洲。","人生，萍梗迹，谁非乐土，何处吾州。","算不须，临歧惝恍迟留。","要看香炉瀑布，丹枫乱、江色凝秋。","真堪与，潇湘暮雨，图上画扁舟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-227","tags":[]},{"id":"poem-6b2e5d2b223a564e22d31816","title":"小游仙诗九十八首 十七","author":"曹唐","dynasty":"唐","verses":["玉诏新除沈侍郎，便分茅土镇东方。","不知今夕游何处，侍从皆骑白凤凰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-e5ca2871-c1e9-4956-9187-830d37b1399e","tags":[]},{"id":"poem-6b37d99b93978f95164f4eb4","title":"闻瀑布冰折","author":"马戴","dynasty":"唐","verses":["万仞冰峭折，寒声投白云。","光摇山月堕，我向石床闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-eb8ca915-d8a4-4468-bfb3-2a657e5551d4","tags":[]},{"id":"poem-6b484f3aa258b405a4748a1e","title":"黄鸟","author":"佚名","dynasty":"先秦","verses":["交交黄鸟，止于棘。谁从穆公？子车奄息。维此奄息，百夫之特。","临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！","交交黄鸟，止于桑。谁从穆公？子车仲行。维此仲行，百夫之防。","临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！","交交黄鸟，止于楚。谁从穆公？子车针虎。维此针虎，百夫之御。","临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-130","tags":[]},{"id":"poem-6b5158d37648fa25f97ba98d","title":"读修睦上人歌篇","author":"李咸用","dynasty":"唐","verses":["李白亡，李贺死。","陈陶赵睦寻相次，须知代不乏骚人。","贯休之后，惟修睦而已矣。","睦公睦公真可畏，开口向人无所忌。","才似烟霞生则媚，直如屈轶佞则指。","意下纷纷造化机，笔头滴滴文章髓。","明月清风三十年，被君驱使如奴婢。","劝君休，莫容易，世俗由来稀则贵。","珊瑚高架五云毫，小小不须烦藻思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f9443135-efc1-4f5a-85d0-991f03bb71d3","tags":[]},{"id":"poem-6b54eba860ff3a9a9f3251d4","title":"偈颂七十一首  其六四","author":"释了惠","dynasty":"宋","verses":["贵如圭璧，贱如泥土。","镇压山川，辉腾今古。","有商量，没价数。","富者得之贫，贫者得之富。","岂不见茶陵山下郁阇梨，骑馿踏断溪桥路。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-780d3019-d5d4-4b3f-9b65-2766ac1302a3","tags":[]},{"id":"poem-6b677fe2fa4fedbcaf462676","title":"示舍弃慕道颂","author":"文益","dynasty":"唐","verses":["东堂不折桂，南华不学僊，却来干竺寺，披衣效坐禅。","禅若效坐得，非想亦何偏。","（经刼守闲，不出生死。","）为报参禅者，须悟道中玄。","如何道中玄，真规自宛然。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-78cd084e-3cf6-4ebd-b6e3-f0731199c046","tags":[]},{"id":"poem-6b67b8e9226f45bea30ea821","title":"远寺钟","author":"李嘉祐","dynasty":"唐","verses":["疎钟何处来，度竹兼拂水。","渐逐微风声，依依犹在耳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-adc558c2-6360-4480-be16-abc304c00cb4","tags":[]},{"id":"poem-6b6fb624d77d7b0649918730","title":"生查子·烟雨晚晴天","author":"魏承班","dynasty":"五代","verses":["烟雨晚晴天，零落花无语。","难话此时心，梁燕双来去。","琴韵对薰风，有恨和情抚。","肠断断弦频，泪滴黄金缕。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-9","tags":[]},{"id":"poem-6b7103ce8ed4f2f6ef7e5280","title":"鹑之奔奔","author":"佚名","dynasty":"先秦","verses":["鹑之奔奔，鹊之彊彊。人之无良，我以为兄！","鹊之彊彊，鹑之奔奔。人之无良，我以为君！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-48","tags":[]},{"id":"poem-6b73daba19bb4651b48a7c7b","title":"有感","author":"赵崇嶓","dynasty":"宋","verses":["舞罢歌停岁月深，当时胜迹尽销沉。","飞云卷雨人争赏，留得佳名尚到今。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-ca765337-b52e-460d-94e5-3fd4aa7b2a0b","tags":[]},{"id":"poem-6b79c83d29b629ca63cd9f3c","title":"马诗二十三首 一","author":"李贺","dynasty":"唐","verses":["龙脊贴连钱，银蹄白踏烟。","无人织锦韂，谁为铸金鞭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-3ad494dc-1f51-4918-bb12-f85f371d5cc6","tags":["马","抒怀","写马","怀才不遇"]},{"id":"poem-6b7c8eb27bc8e0ef62ed9350","title":"夏夜宴明月湖","author":"薛逢","dynasty":"唐","verses":["夏夜宴南湖，琴觞兴不孤。","月摇天上桂，星泛浦中珠。","助照萤随舫，添盘笋迸厨。","圣朝思静默，堪守谷中愚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-83b107b3-f528-4431-9517-98be25067597","tags":[]},{"id":"poem-6b7e41846ae4fed9a64c0bd6","title":"柳（见《分门纂类唐歌诗》残本第七册《草本虫鱼类》卷八。按《全唐诗》卷七三四亦作罗绍威诗。）","author":"罗弘信","dynasty":"唐","verses":["空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7a9a9031-34a9-4faf-a2a3-a9cef5cfc4c1","tags":[]},{"id":"poem-6b8bc986712b7814fdbd22b8","title":"次韵李西美舍人见寄二首  其一","author":"李纲","dynasty":"宋","verses":["虏骑长驱犯帝𬮱，滥陪国论敢谋身。","十年不得关河信，四海犹飞战伐尘。","驾驭英雄归睿主，扶持宗社赖元臣。","自惭老病无长策，徒奉藩条牧细民。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-503030e8-7558-4fff-9f65-2cf068d0157d","tags":[]},{"id":"poem-6b9264141e3f921eaa7e2b28","title":"菊花新·堕髻慵妆来日暮","author":"张先","dynasty":"宋","verses":["堕髻慵妆来日暮。","家在画桥堤下住。","衣缓绛绡垂，琼树袅、一枝红雾。","院深池静娇相妒。","粉墙低、乐声时度。","长恐舞筵空，轻化作、彩云飞去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-334","tags":[]},{"id":"poem-6b9341bd13146cb45305e799","title":"咏史诗 嶓冢","author":"胡曾","dynasty":"唐","verses":["夏禹崩来一万秋，水从嶓冢至今流。","当时若诉胼胝苦，更使何人别九州。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-91514ffb-c29d-4129-81e1-9d89cc13c7e7","tags":[]},{"id":"poem-6b9393b6c22b2b21148b04a4","title":"句","author":"林逢","dynasty":"唐","verses":["白玉飞泉千仞雪，青松蔽日一林风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-dc79c645-1ad3-4baa-af8e-7623ba1d97c9","tags":[]},{"id":"poem-6b94e10d402ebaab6dc36bcf","title":"酬陆少府","author":"高适","dynasty":"唐","verses":["朝临淇水岸，还望卫人邑。","别意在山阿，征途背原隰。","萧萧前村口，唯见转蓬入。","水渚人去迟，霜天雁飞急。","固应不远别，所与路未及。","欲济川上舟，相思空伫立。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-cb1ed1bb-9a23-42f5-94b7-fb065fa6d411","tags":[]},{"id":"poem-6b95737b079f73af988bc3e6","title":"敦煌廿咏（并序） 十三、墨池咏","author":"敦煌人作品[一]","dynasty":"唐","verses":["昔人精篆素，尽妙许张芝。","草圣雄千古，芳名冠一时。","舒笺行鸟迹，研墨染鱼缁。","长想临池处，兴来聊咏诗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-41757dd8-3bbb-4763-b8a4-53ad001585c9","tags":[]},{"id":"poem-6ba4d587004bfbe36632e8ac","title":"关河令・清商怨·秋阴时晴渐向暝","author":"周邦彦","dynasty":"宋","verses":["秋阴时晴渐向暝，变一庭凄冷。","伫听寒声，云深无雁影。","更深人去寂静。","但照壁、孤灯相映。","酒已都醒，如何消夜永。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-244","tags":["宋词三百首"]},{"id":"poem-6ba8ce7bdd2587fec445fd32","title":"祭汾阴乐章","author":"源光裕","dynasty":"唐","verses":["方丘既膳，嘉飨载谧。","斋敬毕诚，陶匏贵质。","秀毕丰荐，芳俎盈实。","永永福流，其升如日。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d2ee20f6-53b2-4743-836e-518ab9abe749","tags":[]},{"id":"poem-6baa958ee577e42b33e801dc","title":"月渚","author":"释居简","dynasty":"宋","verses":["秀色老千岩，窗虚小鬰蓝。","水明收晚照，沙暝展晴岚。","野饷隠沦共，清游名胜谈。","中秋无好友，举酒便成三。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-b08234f4-e80d-47de-89d0-8c2ab0453339","tags":[]},{"id":"poem-6bafcd96677e15c9734bf41c","title":"谒金门·风丝袅","author":"纳兰性德","dynasty":"清","verses":["风丝袅，水浸碧天清晓。","一镜湿云青未了，雨晴春草草。","梦里轻螺谁扫，帘外落花红小。","独睡起来情悄悄，寄愁何处好。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-61","tags":[]},{"id":"poem-6bb4e9d91a67d4077fe97d92","title":"答王福娘红笺题诗（题拟）","author":"孙棨","dynasty":"唐","verses":["韶妙如何有远图，未能相为信非夫。","泥中莲子虽无染，移入家园未得无。","（见《北里志》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-ec157f71-c18b-4188-8f30-8024077ca1b1","tags":[]},{"id":"poem-6bbc497523a2cedb21f53f6c","title":"岐王席上咏美人","author":"张谔","dynasty":"唐","verses":["半额画双蛾，盈盈烛下歌。","玉杯寒意少，金屋夜情多。","香艳王分帖，裙娇敕赐罗。","平阳莫相妬，唤出不如他。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-738332fd-e464-47c5-854a-3c8907c0420e","tags":[]},{"id":"poem-6bc276650a8361edf005d090","title":"蓦山溪·梅花初谢","author":"毛滂","dynasty":"宋","verses":["梅花初谢，雪后寒微峭。","谁送一城春，绮罗香、风光窈窕。","插花走马，天近宝鞭寒，金波上，玉轮边，不是红尘道。","玻璃山畔，夜色无由到。","深下水晶帘，拥严妆、铅华相照。","珠楼缈缈，人月两婵娟，尊前月，月中人，相见年年好。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-781","tags":[]},{"id":"poem-6bca5d9e5a218b5317106563","title":"立春日游苑迎春","author":"中宗皇帝","dynasty":"唐","verses":["神皐福地三秦邑，玉台金阙九仙家。","寒光犹恋甘泉树，淑景偏临建始花。","彩蝶黄鸎未歌舞，梅香柳色已矜夸。","迎春正启流霞席，暂嘱曦轮勿遽斜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-2fe88983-0ad0-490b-b08a-8c359af920a3","tags":[]},{"id":"poem-6bcafbd62d9cfe63e1945c74","title":"望洞庭湖赠张丞相","author":"孟浩然","dynasty":"唐","verses":["八月湖水平，涵虚混太清。","气蒸云梦泽，波撼岳阳城。","欲济无舟楫，端居耻圣明。","坐观垂钓者，空有羡鱼情。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-6975adab-25d0-40c6-af3a-3a05847e7717","tags":["唐诗三百首","洞庭湖","描写水","山水","八年级上册(课外)","五言律诗","初中古诗","水","带有地名","写水","地名"]},{"id":"poem-6bde64b94ef0a1d92a721fb9","title":"福马郎","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["李旺，你休说新婚在牛氏宅。","(外)孩儿，说便又待怎地？(贴)他须怨我相耽误；归未得，旁人闻，把奴责。","(合)若是到京国，相逢处作个好筵席。","(丑唱)，。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5191","tags":[]},{"id":"poem-6be4bbd3f882cd55dfbfa3ec","title":"秋怀五首 五","author":"鲍溶","dynasty":"唐","verses":["龙荒变露色，燕鴈南为客。","游子声影中，涕零念离析。","四时如车马，转此今与昔。","往叹在空中，存事委幽迹。","翩翩日歛照，朗朗月系夕。","物生春不留，年壮老还迫。","天机杳何为，长寿与松柏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-14f984ba-f8fb-4eb4-ae65-ad5b10233ec3","tags":[]},{"id":"poem-6bed091f0ae750844551ce34","title":"山居诗  其六六","author":"释延寿","dynasty":"宋","verses":["得丧从来事甚均，任缘徒用苦劳神。","野蔬随分堪充口，石室依稀可庇身。","碧海几时无去棹，红衢何日息征轮。","若教求道如求利，举世浑成无事人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-afc85ff8-e076-431a-b703-430dba6f9d98","tags":[]},{"id":"poem-6bef516e676e30810900bbc8","title":"白雪曲","author":"贯休","dynasty":"唐","verses":["列鼎佩金章，泪眼看风枝。","却思食藜藿，身作屠沽儿。","负米无远近，所希升斗归。","为人无贵贱，莫学鸡狗肥。","斯言如不忘，别更无光辉。","斯言如或忘，即安用人为。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-e6c811cb-96d9-457c-98ec-4f68ef2eb3a1","tags":[]},{"id":"poem-6bf64893f8dc243b18336d35","title":"乐仙观","author":"若虚","dynasty":"唐","verses":["乐氏骑龙上碧天，东吴遗宅尚依然。","悟来大道无多事，真后丹元不值钱。","老树夜风虫咬叶，古垣春雨藓生甎。","松倾鹤死桑田变，华表归乡未有年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-21ef5b32-b69e-4e24-a287-a2b4eca01ec9","tags":[]},{"id":"poem-6bfc8705ad11b58a7a464c20","title":"和张仆射塞下曲","author":"钱起","dynasty":"唐","verses":["月黑雁飞高，单于夜遁逃。","欲将轻骑逐，大雪满弓刀。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c8210485-a1f4-4c76-a1f6-2f5e57d39d29","tags":["唐诗三百首","战争","冬天","将军","乐府","边塞","赞美"]},{"id":"poem-6bff4279efa9d43a489eaade","title":"题冠盖里","author":"李德裕","dynasty":"唐","verses":["偶来冠盖里，媿是旧三公。","自喜无兵术，轻裘上閟宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-08640c71-cf9b-4dc3-a65a-12b770c40af6","tags":[]},{"id":"poem-6c04caa46fbd63a31dc73fea","title":"织妇女","author":"苏拯","dynasty":"唐","verses":["伊余尽少女，一种饰螓首。","徒能事机杼，与之作歌舞。","歌舞片时间，黄金翻袖取。","秪看舞者乐，岂念织者苦。","感此尝忆古人言，一妇不织天下寒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-bffd0608-68af-4b82-9f2f-b5539066a68d","tags":[]},{"id":"poem-6c091af3ad146c78c146edf3","title":"行苇","author":"佚名","dynasty":"先秦","verses":["敦彼行苇，牛羊勿践履。方苞方体，维叶泥泥。","戚戚兄弟，莫远具尔。或四之筵，或授之几。","四筵设席，授几有缉御。或献或酢，洗爵奠斝。","醓醢以荐，或燔或炙。嘉肴脾臄，或歌或咢。","敦弓既坚，四𬭤既均，舍矢既均，序宾以贤。","敦弓既句，既挟四𬭤。四𬭤如树，序宾以不侮。","曾孙维主，酒醴维醽，酌以大斗，以祈黄耇。","黄耇台背，以引以翼。寿考维祺，以介景福。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-245","tags":[]},{"id":"poem-6c0f70c109575e5d046d1704","title":"风入松","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["原来他也只是无奈，恁地好似鬼使神差。","便是他当原在家辞赴选，他父母也不从他，这是三不从把他厮禁害。","恁的呵，三不孝亦非其罪。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5243","tags":[]},{"id":"poem-6c1618e97a7ae59d19ed0ec4","title":"升平词十首 五","author":"薛能","dynasty":"唐","verses":["一物至周天，洪纤尽晏然。","车书无异俗，甲子并丰年。","奇技皆归朴，征夫亦服田。","君王故不有，台鼎合韦弦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3234c655-7b1b-4be7-bdc3-7f6c93106dae","tags":[]},{"id":"poem-6c33feccd2d0cac62921ec8f","title":"竹楼","author":"李嘉佑","dynasty":"唐","verses":["傲吏身闲笑五侯，西江取竹起高楼。","南风不用蒲葵扇，纱帽闲眠对水鸥。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-竹樓","tags":[]},{"id":"poem-6c3e7d1495368c532212a1f0","title":"暮秋书怀","author":"崔湜","dynasty":"唐","verses":["首夏别京辅，杪秋滞三河。","沉沉蓬莱阁，日夕乡思多。","霜剪凉墀蕙，风捎幽渚荷。","岁芳坐沦歇，感此至微歌。","（〖1〗按这一首，《全唐诗》卷三一作为魏征的诗，而《珠英集》作崔湜；《珠英集》应可据，故仍补入崔湜名下。","第七句「沦歌」有误，依《全唐诗》应作歇。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-76a778ea-6aeb-46db-96dc-8cc5586ed23d","tags":[]},{"id":"poem-6c3ec141ecd50a53ba7fb5e2","title":"游仙二首 二","author":"司空图","dynasty":"唐","verses":["刘郎相约事难谐，雨散云飞自此乖。","月姊殷勤留不住，碧空遗下水精钗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-4e36541b-bb38-416a-8d20-8cf76dbad6e5","tags":[]},{"id":"poem-6c415f750d38e6540302cf2d","title":"赠别孟郊","author":"张籍","dynasty":"唐","verses":["历历天上星，沉沉水中萍。","幸当清秋夜，流影及微形。","君生衰俗间，立身如礼经。","纯诚发新文，独有金石声。","才名振京国，归省东南行。","停车楚城下，顾我不念程。","宝镜曾坠水，不磨岂自明。","苦节居贫贱，所知赖友生。","欢会方别离，戚戚忧虑幷。","安得在一方，终老无送迎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a888e890-ca60-47f3-a750-3df66492fb8c","tags":[]},{"id":"poem-6c52d3024b85bb7dbba3405f","title":"句","author":"奉蚌","dynasty":"唐","verses":["绿萝翦作三春柳，红锦裁成二月花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0a64b37d-63fe-45fe-b831-7356624b9982","tags":[]},{"id":"poem-6c5abc78e247b8791a0be8f0","title":"鹊桥仙","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["披香随宴，上林游赏，醉后人扶马上。","金莲花炬照回廊，正院宇梅梢月上。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5217","tags":[]},{"id":"poem-6c67ebda973532ccfc8eceae","title":"吊建州李员外","author":"曹松","dynasty":"唐","verses":["铭旌归故里，猿鸟亦凄然。","已葬桐江月，空廻建水船。","客传为郡日，僧说读书年。","恐有吟魂在，深山古木边。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e0f13058-08c4-43b1-bfd7-6208b6800009","tags":[]},{"id":"poem-6c69579f","title":"拟行路难·其四","author":"鲍照","dynasty":"南朝宋","verses":["泻水置平地，各自东西南北流。","人生亦有命，安能行叹复坐愁？","酌酒以自宽，举杯断绝歌路难。","心非木石岂无感？吞声踯躅不敢言。"],"enabled":true,"collection":"历代名篇","source":"《鲍参军集》乐府《拟行路难十八首》其四。","tags":["乐府","抒怀"]},{"id":"poem-6c724d2778e3c37b0cbcc081","title":"古柏","author":"刘望之","dynasty":"宋","verses":["草木长生亦偶然，不须闻此便谈仙。","烧枝竞说丹飞日，举世宁知手种年。","双鹤不归秋自冷，万牛回首句空传。","相逢一饮清阴下，与子前生定有缘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-00721e15-6e6e-4b2f-9e2c-407f0cb6c972","tags":[]},{"id":"poem-6c736f02a2dddd6beb5b07a5","title":"七谏·哀命","author":"东方朔","dynasty":"汉","verses":["哀时命之不合兮，伤楚国之多忧。","内怀情之洁白兮，遭乱世而离尤。","恶耿介之直行兮，世溷浊而不知。","何君臣之相失兮，上沅湘而分离。","测汨罗之湘水兮，知时固而不反。","伤离散之交乱兮，遂侧身而既远。","处玄舍之幽门兮，穴岩石而窟伏。","从水蛟而为徙兮，与神龙乎休息。","何山石之崭岩兮，灵魂屈而偃蹇。","含素水而蒙深兮，日眇眇而既远。","哀形体之离解兮，神罔两而无舍。","惟椒兰之不反兮，魂迷惑而不知路。","愿无过之设行兮，虽灭没之自乐。","痛楚国之流亡兮，哀灵修之过到。","固时俗之溷浊兮，志瞀迷而不知路。","念私门之正匠兮，遥涉江而远去。","念女媭之婵媛兮，涕泣流乎于悒。","我决死而不生兮，虽重追吾何及。","戏疾濑之素水兮，望高山之蹇产。","哀高丘之赤岸兮，遂没身而不反。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-35","tags":[]},{"id":"poem-6c7406e80ff2d1f50e9b6be5","title":"河传·去去","author":"李珣","dynasty":"五代","verses":["去去，何处？迢迢巴楚，山水相连。","朝云暮雨，依旧十二峰前，猿声到客船。","愁肠岂异丁香结？因离别，故国音书绝。","想佳人花下，对明月春风，恨应同。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-48","tags":[]},{"id":"poem-6c76ab1ae0ebfef6b30cf5af","title":"次韵司徒富公耆年会诗","author":"苏颂","dynasty":"宋","verses":["古人称宴安，居处必择地。","诸公来河南，有若不期会。","岩岩大司徒，早辞槐鼎贵。","嘉谟纳渊衷，故事留台寺。","构第铜驼坊，开门瀍水次。","居守德爵同，位重官三事。","高轩每过从，纵言谈道艺。","复有乡里贤，夙昔承嘉惠。","崧岭高横空，洛波清见底。","履道追昔游，行厨载芳醴。","燕毛礼所重，安车皆戾止。","年尊二国公，齿序众君子。","愿公寿千秋，慰民瞻具尔。","三载一来朝，当陪天子祀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-4ef801a6-2023-4f38-9fab-815a686a19d7","tags":[]},{"id":"poem-6c784f8e48ce019a2c526b63","title":"和孙秀才与弟醉饮","author":"华镇","dynasty":"宋","verses":["醺酣归至乐，曲糵古来贤。","荆树同株日，萧斋欲雪天。","倾颓叔夜玉，臬兀季真船。","熟览新诗意，依稀识道筌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-77fd65b6-038e-42fd-87a2-9c977efa3309","tags":[]},{"id":"poem-6c7b708d6d11177743deecf0","title":"谢朱常侍寄贶蜀茶剡纸二首 二","author":"崔道融","dynasty":"唐","verses":["百幅轻明雪未融，薛家凡纸漫深红。","不应点染闲言语，留记将军盖世功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9882b179-0e51-4177-a7bd-bcbed5160927","tags":[]},{"id":"poem-6c7b866a84ae767043370f6a","title":"小重山·一闭昭阳春又春","author":"韦庄","dynasty":"五代","verses":["一闭昭阳春又春，夜寒宫漏永，梦君恩。","昏思陈事暗消魂，罗衣湿，红袂有啼痕。","歌吹隔重阍，绕庭芳草绿，倚长门。","万般惆怅向谁论？凝情立，宫殿欲黄昏。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-25","tags":[]},{"id":"poem-6c7d1cb5021bd432d2b3f98f","title":"奉和宫傅相公怀旧见寄四十韵","author":"徐铉","dynasty":"宋","verses":["谢傅功成德望全，鸾台初下正萧然。","抟风乍息三千里，感旧重怀四十年。","西掖新官同贾马，南朝兴运似开天。","文辞职业分工拙，流辈班资让后先。","每愧陋容劳刻画，长惭顽石费雕镌。","晨趋纶掖吟春永，夕会精庐待月圆。","立马有时同草诏，联镳几处共成篇。","闲歌柳叶翻新曲，醉咏桃花促绮筵。","少壮况逢时世好，经过宁虑岁华迁。","云龙得路须腾跃，社栎非材合弃捐。","再谒湘江犹是幸，两还宣室竟何缘。","已知瑕玷劳磨莹，又得官司重接连。","听漏分宵趋建礼，从游同召赴甘泉。","云开阊阖分台殿，风过华林度管弦。","行止不离宫仗影，衣裾尝惹御炉烟。","师资稷契论中礼，依止山公典小铨。","多谢天波垂赤管，敢教晨景过华砖。","翾飞附骥方经远，巨楫垂风遂济川。","玉烛调时钧轴正，台阶平处德星悬。","岩廊礼绝威容肃，布素情深友好偏。","长拟营巢安大厦，忽经操钺领中权。","吴门日丽龙衔节，京口沙晴鹢画船。","盖代名高方赫赫，恋恩心切更干干。","袁安辞气忠仍恳，吴汉精诚直且专。","却许丘明师纪传，更容疏广奉周旋。","朱门自得施行马，厚禄何妨食万钱。","密疏尚应劳献替，清谈唯见论空玄。","东山妓乐供闲步，北牖风凉足晏眠。","玄武湖边林隠见，五城桥下棹洄沿。","曾移苑树开红药，新凿家池种白莲。","不遣前驺妨野逸，别寻逋客互招延。","棋枰寂静陈虚阁，诗笔沉吟劈彩牋。","往事偶来春梦里，闲愁因动落花前。","青云旧侣嗟谁在，白首亲情倍见怜。","尽日凝思殊怅望，一章追叙信精研。","韶颜莫与年争竞，世虑须凭道节宣。","幸喜书生为将相，定由阴德致神仙。","羊公剩有登临兴，尚子都无嫁娶牵。","退象天山镇浮竞，起为霖雨润原田。","从容自保君臣契，何必扁舟始是贤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-a9034174-f585-4118-b92b-eee02d8054de","tags":[]},{"id":"poem-6c840d6f95764a17b27cdc6d","title":"招隐山观玉蘂树戏书即事奉寄江西沈大夫阁老","author":"李德裕","dynasty":"唐","verses":["玉蘂天中树，金闺昔共窥。","落英闲舞雪，密叶乍低帷旧赏烟霄远，前欢岁月移。","今来想颜色，还似忆琼枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2f3433fb-a4d9-4cf4-b96c-ba047505806c","tags":[]},{"id":"poem-6c867b9067ecc68690dea0c9","title":"咏鱼鼓二首 二","author":"义存","dynasty":"唐","verses":["可怜鱼鼓子，天生从地养。","粥饭不能{歹肖}，空肚作声响。","时时惊僧睡，懒者烦恼长。","住持闹喧喧，不如打游漾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-e126ec74-bf49-413d-b423-91e6b9c189fd","tags":[]},{"id":"poem-6c89b3bbe2f4c19f5ef9dd28","title":"雪巢三首  其一","author":"林宪","dynasty":"宋","verses":["居闲我所愿，谋拙人所虑。","平淡固可嘉，饥来欲谁诉。","八十日彭泽，四十年郑圃。","前贤去就意，三复成喜惧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-60ee2d17-1b05-42a9-8068-1e2b06527307","tags":[]},{"id":"poem-6ca10a14aa54fc85b3ecae46","title":"过张氏水亭","author":"释居简","dynasty":"宋","verses":["到岸不多遥，晴初雪未消。","茆簷虽傍水，人影不随潮。","鹊占寒枝喜，鱼从落日跳。","丹枫莫吹尽，我欲系兰桡。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-8212c63d-79f0-4587-a498-5e8b858d3ae4","tags":[]},{"id":"poem-6ca7dc3baeaef82a3c946395","title":"同苗员外宿荐福常师房","author":"司空曙","dynasty":"唐","verses":["浮生共多故，聚宿喜君同。","人息时闻磬，灯摇乍有风。","霜堦疑水际，夜木似山中。","一愿持如意，长来事远公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-47948a17-85bc-4a79-815b-888a7c0a47a4","tags":[]},{"id":"poem-6caa9e4ac790f3c2fba0ece3","title":"更漏子·秋色清","author":"毛熙震","dynasty":"五代","verses":["秋色清，河影淡，深户烛寒光暗。","绡幌碧，锦衾红，博山香炷融。","更漏咽，蛩鸣切，满院霜华如雪。","新月上，薄云收，映帘悬玉钩。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-42","tags":[]},{"id":"poem-6caaa73fb1569f72489228d3","title":"加颂蜀僧雪颂  其一","author":"释印肃","dynasty":"宋","verses":["庭前雪子落纷纷，妙触灵明应普门。","不是药山无用处，权令庞老警儿孙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-a4689ed9-d436-430c-a600-4d8fc2fe812d","tags":[]},{"id":"poem-6caac18a31e4e506b547c5ae","title":"南浦·风悲画角","author":"孔夷","dynasty":"宋","verses":["风悲画角，听单于、三弄落谯门。","投宿征骑，飞雪满孤村。","酒市渐闲灯火，正敲窗、乱叶舞纷纷。","送数声惊雁，下离烟水，嘹唳度寒云。","好在半胧溪月，到如今、无处不销魂。","故国梅花归梦，愁损绿罗裙。","为问暗香闲艳，也相思、万点付啼痕。","算翠屏应是，两眉馀恨倚黄昏。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-245","tags":["宋词三百首"]},{"id":"poem-6cb55524d8201d538660cf77","title":"代书寄泗州钱侍郎","author":"徐铉","dynasty":"宋","verses":["起部纡两绶，恢恢刃有余。","既为侍中郎，又复专城居。","无久恋铃阁，早应还直庐。","浚川春水满，珍重寄双鱼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-2e60b63b-514c-4a85-baba-ffcd70b49463","tags":[]},{"id":"poem-6cbd6c7e3045e1eadd6e4d41","title":"酬李如山见寄","author":"释居简","dynasty":"宋","verses":["俗棼须尽扫，扫尽又纷华。","喧避蚁争市，静看蜂报衙。","竹梢斑殒箨，苹渚素浮花。","自把闲消遣，从容日又斜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-0dbeec49-1bbf-4a3b-a354-be34f6ea3840","tags":[]},{"id":"poem-6cc06f4ef5b784c2443f3d28","title":"将入匡山别芳昼二公二首 二","author":"贯休","dynasty":"唐","verses":["红豆树间滴红雨，恋师不得依师住。","世情世界愁杀人，锦绣谷中归舍去。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-39b52015-5f01-4243-ba21-b1e7289c9326","tags":["庐山"]},{"id":"poem-6cc0b0b91dfb51d11b39469e","title":"白水县崔少府十九翁高斋三十韵","author":"杜甫","dynasty":"唐","verses":["客从南县来，浩荡无与适。","旅食白日长，况当朱炎赫。","高斋坐林杪，信宿游衍阒。","清晨陪跻攀，傲睨俯峭壁。","崇冈相枕带，旷野怀咫尺。","始知贤主人，赠此遣愁寂。","危阶根青冥，曾冰生淅沥。","上有无心云，下有欲落石。","泉声闻复急，动静随所击。","鸟呼藏其身，有似惧弹射。","吏隐道性情，兹焉其窟宅。","白水见舅氏，诸翁乃仙伯。","杖藜长松阴，作尉穷谷僻。","为我炊雕胡，逍遥展良觌。","坐久风颇愁，晚来山更碧。","相对十丈蛟，歘翻盘涡坼。","何得空里雷，殷殷寻地脉。","烟氛蔼崷崪，魍魉森惨戚。","昆仑崆峒颠，回首如不隔。","前轩颓反照，巉绝华岳赤。","兵气涨林峦，川光杂锋镝。","知是相公军，铁马云雾积。","玉觞淡无味，胡羯岂强敌。","长歌激屋梁，泪下流衽席。","人生半哀乐，天地有顺逆。","慨彼万国夫，休明备征狄。","猛将纷填委，庙谋蓄长策。","东郊何时开，带甲且来释。","欲告清宴罢，难拒幽明迫。","三叹酒食旁，何由似平昔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-40806e64-bb99-458f-a2a0-046eed040b76","tags":[]},{"id":"poem-6cc8fe4655f4f0281dc03a5a","title":"风流子·金络玉衔嘶马","author":"孙光宪","dynasty":"五代","verses":["金络玉衔嘶马，系向绿杨阴下。","朱户掩，绣帘垂，曲院水流花谢。","欢罢，归也，犹在九衢深夜。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-27","tags":[]},{"id":"poem-6cc98e492281f6077294ba18","title":"句 五","author":"罗隐","dynasty":"唐","verses":["一列珠帘不下钩。","（《后村千家诗》卷十六闻人祥正《集句》引。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4b874242-9696-4dfe-ab73-bc20a1df112b","tags":[]},{"id":"poem-6ccc481e98f4ac1b9c05681f","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["江陵在眼前。","(合)五鸡山至。","(净)如投着地脉。","(合)不辞迢递。","(生)快行时我赏你。","(合)领台旨。","(净)回马不用鞭。","(合)不觉过一里又一里。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2676","tags":[]},{"id":"poem-6ccdd276ced1b72cb747bbd5","title":"仙吕/点绛唇","author":"杨景贤","dynasty":"元","verses":["宝殿生香，美人扶向，瑶阶上。","列七宝旌幢，端坐泥金亢。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2326","tags":[]},{"id":"poem-6cd3553b10a0027fc9821dc4","title":"观猎骑","author":"司空曙","dynasty":"唐","verses":["缠臂绣纶巾，貂裘窄称身。","射禽风助箭，走马雪翻尘。","金埒争开道，香车为驻轮。","翩翩不知处，传是霍家亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-4ea9c5d8-c3dd-45cf-911e-e602fca2ff75","tags":[]},{"id":"poem-6cdcb5e23e6d5f0e1bd0e55b","title":"游虞山兴福寺","author":"周才","dynasty":"宋","verses":["兴福相传古道场，杖藜乘兴访支郎。","案翻梵贝烟消篆，院寂棋声日转廊。","玉版参师多古意，石梅问讯几时香。","禅家识得诗风味，清供杯茶熟煮汤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-eab50069-4a17-4184-bf02-c555317c6f3f","tags":[]},{"id":"poem-6ce4ec8cc7cd5353cff10aca","title":"西江月·若将花卉论行藏","author":"李结","dynasty":"宋","verses":["若将花卉论行藏。","盍在凌烟阁上。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-179","tags":[]},{"id":"poem-6cecb9a6aed959337dbd28cc","title":"降虏","author":"赵嘏","dynasty":"唐","verses":["广武溪头降虏稀，一声寒角怨金微。","河湟不在春风地，歌舞空裁雪夜衣。","铁马半嘶边草去，狼烟高映塞鸿飞。","扬雄尚白相如吃，今日何人从猎归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-307d584e-b839-4f4c-a11e-708bbf515eee","tags":[]},{"id":"poem-6ced98468378410bb9755dfe","title":"风不鸣条","author":"黄颇","dynasty":"唐","verses":["五纬起祥飙，无声瑞圣朝。","稍开含露蘂，才转惹烟条。","密叶应潜变，低枝几暗摇。","林间莺欲啭，花下蝶微飘。","初满沿堤草，因生逐水苗。","太平无一事，天外奏虞韶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-7bee6ea7-4c8e-4c50-972a-82cac662b932","tags":[]},{"id":"poem-6cedd19981632739b03eb082","title":"送舍弟","author":"李嘉祐","dynasty":"唐","verses":["诸谢偏推永嘉守，三何独许水曹郎。","老兄鄙思难俦匹，令弟清词堪比量。","叠嶂入云藏古寺，高秋背月转南湘。","定知马上多新句，早寄袁溪当八行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-df2faabf-b5ef-4c87-8091-da1a91285122","tags":[]},{"id":"poem-6cf4e796dffbb9e76558256c","title":"古塞上曲七首 三","author":"贯休","dynasty":"唐","verses":["白雁兼羌笛，几年垂泪听。","阴风吹杀气，永日在青冥。","远戍秋添将，边烽夜杂星。","嫖姚头半白，犹自看兵经。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-74e6902f-8152-4c25-84e3-b6dc1965eb78","tags":[]},{"id":"poem-6cf5bc810fe491cd9a363f4c","title":"送下博陈员外","author":"徐铉","dynasty":"宋","verses":["旷望丛台路，飘飖楚塞人。","琴堂无故旧，何计免沾巾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c506cd61-4c4d-422e-99a1-e47f388d57c6","tags":[]},{"id":"poem-6cfa2f7f475db40b009b398d","title":"望江南・忆江南·江南酒","author":"王琪","dynasty":"宋","verses":["江南酒，何处味偏浓。","醉卧春风深巷里，晓寻香旆小桥东。","竹叶满金锺。","檀板醉，人面粉生红。","青杏黄梅朱阁上，鲥鱼苦笋玉盘中。","酩酊任愁攻。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-843","tags":[]},{"id":"poem-6d034b414681ec8edf53fb01","title":"尾声","author":"徐田臣《杀狗记》","dynasty":"元","verses":["自古及今结义的，除非管鲍更有谁？那一个人情得到底？院君，员外回来，怎生谏他一谏便好？(旦)是如此。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1724","tags":[]},{"id":"poem-6d037cc0ad023f4c503e7b7c","title":"别离曲","author":"张籍","dynasty":"唐","verses":["行人结束出门去，几时更踏门前路。","忆昔君初纳采时，不言身属辽阳戍。","早知今日当别离，成君家计良为谁。","男儿生身自有役，那得误我少年时。","不如逐君征战死，谁能独老空闺里。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e746df5e-8161-458b-8bbf-4ca3f3c90b91","tags":[]},{"id":"poem-6d0662da0ce2be492ae90161","title":"长安遇冯著","author":"韦应物","dynasty":"唐","verses":["客从东方来，衣上灞陵雨。","问客何为来，采山因买斧。","冥冥花正开，飏飏燕新乳。","昨别今已春，鬓丝生几缕。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b8ae44b3-ba8d-42d3-85a7-a70aa8608379","tags":["唐诗三百首","叙事","同情","抒情","五言古诗"]},{"id":"poem-6d068c06067a0ce6225eab9a","title":"菩萨蛮 其十二","author":"温庭筠","dynasty":"唐","verses":["夜来皓月才当午，重帘悄悄无人语。","深处麝烟长，卧时留薄妆。","当年还自惜，往事那堪忆。","花落月明残，锦衾知晓寒。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-11","tags":[]},{"id":"poem-6d07802d597aa6188892bec1","title":"八三","author":"王梵志","dynasty":"唐","verses":["布施生生富，（「富」，斯三三九三卷作「福」。","）悭贪世世贫。","若人苦悭惜，却却受辛懃。","（「却却」，戴密微、项楚校作「劫劫」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5a3e0739-22af-4638-9a28-94fbfec1b0ec","tags":[]},{"id":"poem-6d0e34ca6852f74296768a8b","title":"叹景禅吟","author":"道怤","dynasty":"唐","verses":["叹汝景禅去何速，虽不同道当眼明。","个今永却不曾亏，地水火风还故国。","好也好，也大奇，忙忙宇宙几人知，莹净宁闲追路绝，青山绿嶂白云驰。","歌好歌，笑好笑，谁肯便作此中调。","难提既与君凑机，其肯无不谐其要。","格志异，气骨高，森萝咸会一灵毫。","虽然示作皆同电，出岫藏峰徒思劳。","希奇地，剑吹毛，脱罩腾笼任性游。","此界他界如水月，几般应迹妙逍遥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-99ed0f91-a7e8-49b8-8839-c7ebf4851ad0","tags":[]},{"id":"poem-6d1f927d1360d250ce4fe4fe","title":"古出塞曲三首 一","author":"贯休","dynasty":"唐","verses":["扫尽狂胡迹，回头望故关。","相逢惟死鬬，岂易得生还。","纵宴参胡乐，收兵过雪山。","不封十万户，此事亦应闲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-53b39de2-aa4e-420a-b55d-d4b3c6a423e7","tags":[]},{"id":"poem-6d2d7d5ac1b69aad845e98d4","title":"玉楼春·今朝何以为公寿","author":"毛滂","dynasty":"宋","verses":["今朝何以为公寿。","极贵长年公素有。","庭阶不乏长芝兰，少翁又是廷臣右。","三能粲粲依魁秀。","八柱魏魏蟠地厚。","皇家卜册万斯年，年光长转洪钧手。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-791","tags":[]},{"id":"poem-6d33cf72d165c6bbb01b0d61","title":"贞元八年十二月谒先主庙绝句三首 三","author":"张俨","dynasty":"唐","verses":["雄名垂竹帛，荒陵压阡陌。","终古更何闻，悲风入松栢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1bf291c4-1fe4-4a1c-93e9-638a3330c7d6","tags":[]},{"id":"poem-6d347a902f6fb62cb1d7aa7b","title":"句  其一","author":"林迥","dynasty":"宋","verses":["门前红日海千里，池上白莲山四邻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-f768722b-94b1-4010-b713-c2ec207e8e49","tags":[]},{"id":"poem-6d37b40ddf23b003e03cd2bd","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["我只是不还赁钱。","(净)赶出去桥亭上眠。","(生)看取同人劝您。","(末)休要出言恁偏。","(丑)你弄拳！(净)我弄拳？(生末合)看口休得要斗煎。","(净)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2598","tags":[]},{"id":"poem-6d3a05b78c6b0719455afe4c","title":"题壁","author":"杨凝式","dynasty":"唐","verses":["院似禅心静，花如觉性圆。","自然知了义，争肯学神仙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c1847ed8-c71b-4e23-adb5-2cb4bdfeb836","tags":[]},{"id":"poem-6d3bf6dac788752c16a21aaa","title":"唐大飨拜洛乐章 归和","author":"则天皇后","dynasty":"唐","verses":["调云阕兮神座兴，骖云驾兮俨将升。","腾绛霄兮垂景祜，翘丹恳兮荷休征。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ab15b93a-75c9-4665-89a5-7c64bf2dc484","tags":[]},{"id":"poem-6d4022cafef5e72f4885a8ca","title":"劝僧还乡","author":"宋伯仁","dynasty":"宋","verses":["世事无过尔尔，禅心只好休休。","江上数峰如削，西风不碍归舟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b3099359-109d-4ad1-b5d6-b4857c625231","tags":[]},{"id":"poem-6d450037950d5cce3ad6e914","title":"小毖","author":"佚名","dynasty":"先秦","verses":["予其惩，而毖后患。莫予荓蜂，自求辛螫。肇允彼桃虫，拚飞维鸟。未堪家多难，予又集于蓼。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-288","tags":[]},{"id":"poem-6d4a18442a3ff4ef7557a14b","title":"浣溪沙·钿匣菱花锦带垂","author":"薛昭蕴","dynasty":"五代","verses":["钿匣菱花锦带垂，静临栏槛卸头时，约鬟低珥算归期。","茂苑草青湘渚阔，梦余空有漏依依，二年终日损芳菲。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-27","tags":[]},{"id":"poem-6d4dbb338aa09d4ae62f14b5","title":"咏古十六首  其一六","author":"华镇","dynasty":"宋","verses":["兰芷生幽薄，浥露搴华姿。","芙容隔秋江，扁舟满江湄。","丈夫抱材用，但愿君王知。","宁生击牛角，载歌南山词。","词终脱裋褐，缨佩暮萎蕤。","人事非有定，斯言或难持。","翩翩李将军，鸣弦压由基。","余威震戎虏，谈笑静边陲。","桃李曾无言，嘉声满黄扉。","心知堪万户，乃谓生匪时。","烽火照甘泉，未能包虎皮。","目视汉飞将，弃弃轻如遗。","颇牧已黄土，忉忉勤缅思。","如何中林士，坐视青云期。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-caceaa82-856e-4dfb-bf67-fbfd520c5f76","tags":[]},{"id":"poem-6d4e44642b4b2e5f9044ed9c","title":"风入松","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(小生)你与哥哥结义胜嫡亲，敢恁的反面忘恩！我哥哥行使些糖蜜口，我根底刁唆休论。","我哥哥有眼何曾识好人？你只宜假不宜真。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1826","tags":[]},{"id":"poem-6d4e845510e3701ef3d25fde","title":"郊庙歌辞 享太庙乐章 崇德舞","author":"不详","dynasty":"唐","verses":["五运改卜，千龄启圣。","彤云晓聚，黄星夜映。","叶阐珠囊，基开玉镜。","下临万宇，上齐七政。","雾开三象，尘清九服。","海溓星晖，远安迩肃。","天地交泰，华夷辑睦。","翔泳归仁，中外禔福。","绩逾黜夏，勋高翦商。","武陈七德，刑设三章。","祥禽巢阁，仁兽游梁。","卜年惟永，景福无疆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-064b1fa2-3649-4b01-a0c0-4bc73c9d8a89","tags":[]},{"id":"poem-6d64251eeb83499facf3ff41","title":"风入松·听风听雨过清明","author":"吴文英","dynasty":"宋","verses":["听风听雨过清明。","愁草瘗花铭。","楼前绿暗分携路，一丝柳、一寸柔情。","料峭春寒中酒，交加晓梦啼莺。","西园日日扫林亭。","依旧赏新晴。","黄蜂频扑秋千索，有当时、纤手香凝。","惆怅双鸳不到，幽阶一夜苔生。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-7","tags":["宋词三百首"]},{"id":"poem-6d678fa15af9e2305fbe0cb4","title":"兵要望江南 《周易》占候第二十六（三十七首） 八","author":"易静","dynasty":"唐","verses":["内卦我，外卦属他邦。","内尅外时无大损（辛本、川本作「攒捷」），子孙发动急旋（辛本、川本作「施」）张，大战我军强。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-48d735df-675d-43b9-923a-e850afeddc47","tags":[]},{"id":"poem-6d6862c9d7dd8b72d3ba527d","title":"咏怀古迹五首 一","author":"杜甫","dynasty":"唐","verses":["支离东北风尘际，漂泊西南天地间。","三峡楼台淹日月，五溪衣服共云山。","羯胡事主终无赖，词客衰时且未还。","庾信平生最萧瑟，暮年诗赋动江关。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-03eb4001-023a-4920-bbc7-a0fc52b2836d","tags":["唐诗三百首","隋・唐・五代","七言律诗","感叹","怀古"]},{"id":"poem-6d700154cd64eb7c91f426a3","title":"尾声","author":"徐田臣《杀狗记》","dynasty":"元","verses":["悲欢离合情千古，雪月风花景四时，女貌郎才能有几？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1844","tags":[]},{"id":"poem-6d7052c7188545d52f96f086","title":"右军墨池","author":"刘言史","dynasty":"唐","verses":["永嘉人事尽归空，逸少遗居蔓草中。","至今池水涵余墨，犹共诸泉色不同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-0083f12c-2f19-4008-bf97-41445b57ab40","tags":[]},{"id":"poem-6d73b8b46983a7e3208959fb","title":"咏棋子赠弈僧","author":"张乔","dynasty":"唐","verses":["黑白谁能用入玄，千回生死体方圆。","空门说得恒沙劫，应笑终年为一先。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d9fc1ad3-4fce-4ba4-8582-bb6ec792ab67","tags":[]},{"id":"poem-6d7d0e32eb6ba1ac9235ca0c","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(丑)道消遣长空叹嗟，画堂中且安享骄奢。","看纷纷绿拥红遮，绮罗香散沉麝。","辟寒犀开元此日，曾远贡喧传朝野。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8328","tags":[]},{"id":"poem-6d8690556d4b647315ed09f0","title":"秋日同僧宿西池","author":"刘得仁","dynasty":"唐","verses":["菡萏遍秋水，隔林香似焚。","僧同池上宿，霞向月边分。","渚鸟栖蒲立，城砧接曙闻。","来宵莫他约，重此话孤云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2b52ca1a-7472-4e9c-a758-8a1a2bd17b18","tags":[]},{"id":"poem-6d8e4efdb7d7f281d8a6f8a8","title":"解语花·风销焰蜡","author":"周邦彦","dynasty":"宋","verses":["风销焰蜡，露烘炉。","花市光相射。","桂华流瓦。","纤云散，耿耿素娥欲下。","衣裳淡雅。","看楚女、纤腰一把。","箫鼓喧，人影参差，满路飘香麝。","因念都城放夜。","望千门如昼，嬉笑游冶。","钿车罗帕。","相逢处，自有暗尘随马。","年光是也。","唯只见、旧情衰谢。","清漏移，飞盖归来，从舞休歌罢。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-233","tags":["宋词三百首"]},{"id":"poem-6d8e8758fef881237073c9b6","title":"上元书怀","author":"司马光","dynasty":"宋","verses":["老去春无味，年年觉病添。","酒因脾积断，灯为目阿嫌。","势位非其好，纷华已久厌。","唯余读书乐，暖日坐前簷。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-a7a905b1-fdf5-4ee4-9440-787f09b48293","tags":[]},{"id":"poem-6d9509c21f3373463672cbb0","title":"游长宁公主流杯池二十五首 一","author":"上官昭容","dynasty":"唐","verses":["逐仙赏，展幽情。","逾昆阆，迈蓬瀛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-788b3936-5fdc-4ee4-b414-f9ab803c95f9","tags":[]},{"id":"poem-6d9bdc07f74fc3acdb64013c","title":"赠安道士","author":"陈造","dynasty":"宋","verses":["吴罝传世皆妙语，善升乃近崔遵度。","丝桐造妙诗疑神，古来多属方外人。","羡君矫矫云山客，子墨桐君生莫逆。","此人此艺吾了然，锦囊杰句多时贤。","月斧云斤且游戏，缠声鹿鸣莫经意。","古人进艺道与俱，如君不应古与殊。","谒帝行如稷丘子，莫谩瓜芋嗤侯喜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-d0066048-505e-4380-90fb-a3cd682c1f58","tags":[]},{"id":"poem-6d9cb941b85a8a2bed95f883","title":"山花子·莺锦蝉縠馥麝脐","author":"和凝","dynasty":"五代","verses":["莺锦蝉縠馥麝脐，轻裾花早晓烟迷。","㶉𫛶战金红掌坠，翠云低。","星靥笑偎霞脸畔，蹙金开襜衬银泥。","春思半和芳草嫩，碧萋萋。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-18","tags":[]},{"id":"poem-6d9d7c13ffbbebb8d3b17143","title":"豪家夏冰咏","author":"雍裕之","dynasty":"唐","verses":["金错银盘贮赐冰，清光如耸玉山棱。","无论尘客闲停扇，直到消时不见蝇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-dd0df055-d7b9-4fae-b979-ec07e0608cc4","tags":[]},{"id":"poem-6da1a88737fdc0faf2ea4cee","title":"清明日宴梅道士房","author":"孟浩然","dynasty":"唐","verses":["林卧愁春尽，开轩览物华。","忽逢青鸟使，邀入赤松家。","丹灶初开火，仙桃正落花。","童颜若可驻，何惜醉流霞。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d2b5090e-e6fe-4d4f-9dd6-fe94ff6d4b5c","tags":["唐诗三百首","五言律诗"]},{"id":"poem-6da801353ba12078a0e48b05","title":"赠吴官","author":"王维","dynasty":"唐","verses":["长安客舍热如煮，无个茗糜难御暑。","空摇白团其谛苦，欲向缥囊还归旅。","江乡鲭鲊不寄来，秦人汤饼那堪许。","不如侬家任挑达，草𪨗捞虾富春渚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-14831423-609e-4625-8bac-e9feb8e295a6","tags":[]},{"id":"poem-6da883acc96001087d8a74bd","title":"卖花声","author":"无名氏《张协状元》","dynasty":"元","verses":["那日红楼数里，要纳夫婿，谁知道苦相嫌弃？(净扶后出接)孩儿饮气，尽日没情没绪。","阿娘怎知，恹恹害自觉着体。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2637","tags":[]},{"id":"poem-6da954105c443bd8613b8358","title":"神功盛德诗  其二○","author":"华镇","dynasty":"宋","verses":["天命靡常，惟德惟功。","神圣有作，历数在躬。","正位东朝，遂成大宗。","协和万邦，万邦以雍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b6a7135b-4ae3-45ad-af76-5e6c2acbc5f7","tags":[]},{"id":"poem-6db00f0fe9d7838888e21e88","title":"题束道辅怀疏亭二首  其一","author":"刘跂","dynasty":"宋","verses":["逢时乐宦达，既达贵蚤休。","东门两归客，冉冉不可留。","大夫名贤后，出处亦俱优。","筑室在何许，南郭林塘幽。","安车摇佩鱼，步屧随杖鸠。","胜日至佳客，懽颜终献酬。","鄙人最樗散，世用一何缪。","政以无事身，尊俎常见收。","令年扫三径，近不隔虎丘。","欲问杜陵老，来往几风流。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-0afb9e87-0b24-4529-ba3f-d84333ff5ded","tags":[]},{"id":"poem-6db9fa5238d8c307fa47c967","title":"好事近·丝管闹南湖","author":"晁补之","dynasty":"宋","verses":["丝管闹南湖，湖上醉游时晚。","独看小桥官柳，泪无言偷满。","坐中谁唱解愁辞，红妆劝金盏。","物是奈人非是，负东风心眼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-195","tags":[]},{"id":"poem-6dbf1b145c710915dea27d81","title":"玉楼春·三月初三春渐老","author":"杜安世","dynasty":"宋","verses":["三月初三春渐老。","遍地残花风暗扫。","命俦啸侣拥笙歌，临水泛觞游宴好。","浮利浮名何足道。","丽景芳时须笑傲。","今年不似去年欢，云海路长天杳杳。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-895","tags":[]},{"id":"poem-6dbf4838fdada98c1a266853","title":"郊庙歌辞 明皇祀圜丘乐章 豫和","author":"不详","dynasty":"唐","verses":["至矣丕搆，烝哉太平。","授牺膺箓，复禹继明。","草木仁化，凫鹥颂声。","祀宗陈德，无媿斯诚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-70860658-4a7c-4f94-b2cc-80a5afe07c67","tags":[]},{"id":"poem-6dc505d3294c944ce8b14ea1","title":"秋原野望","author":"杨凌","dynasty":"唐","verses":["客鴈秋来次第逢，家书频寄两三封。","夕阳天外云归尽，乱见青山无数峰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-32f64e23-40d7-4bd1-a43b-5a94c6d57438","tags":[]},{"id":"poem-6dc759c38dcd72a5b06bf372","title":"同玉真公主过大哥山池","author":"明皇帝","dynasty":"唐","verses":["地有招贤处，人传乐善名。","鹜池临九达，龙岫对层城。","桂月先秋冷，苹风向晚清。","凤楼遥可见，仿佛玉箫声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-31f91bce-39c0-4eb6-b905-c344eb337ecf","tags":[]},{"id":"poem-6dc7d1cb18b96691e07586ae","title":"八九","author":"王梵志","dynasty":"唐","verses":["闻钟身须侧，卧转莫前眠。","（「前」，伯三六五六卷作「缠」。","）万一无常去，免至狱门边。","（「边」，伯三六五六卷作「前」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-551dce14-03f9-4506-876f-4b6f93afdae9","tags":[]},{"id":"poem-6dca7fe02f52d260f7a075d6","title":"苦雨寄房四昆季","author":"高适","dynasty":"唐","verses":["独坐见多雨，况兹兼索居。","茫茫十月交，穷阴千里余。","弥望无端倪，北风击林箊。","白日渺难覩，黄云争卷舒。","安得造化功，旷然一扫除。","滴沥簷宇愁，寥寥谈笑疎。","泥涂拥城郭，水潦盘丘墟。","惆怅悯田农，裴回伤里闾。","曾是力井税，曷为无斗储。","万事切中怀，十年思上书。","君门嗟缅邈，身计念居诸。","沈吟顾草茅，郁怏任盈虚。","黄鹄不可羡，鸡鸣时起予。","故人平台侧，高馆临通衢。","兄弟方荀陈，才华冠应徐。","弹棋自多暇，饮酒更何如。","知人想林宗，直道慙史鱼。","携手风流在，开襟鄙吝祛。","宁能访穷巷，相与对园蔬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-20aa930c-017e-4a7d-8909-0782047d574d","tags":[]},{"id":"poem-6dcfba77be059b4dc0623b23","title":"句  其二","author":"曾诚","dynasty":"宋","verses":["椎冰小鲤应堪鲙，扫岸疏梅未放花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-a8cefc73-6777-4fca-9f72-2d0793a87f34","tags":[]},{"id":"poem-6dd46ed2483049e0041d0c71","title":"落第","author":"赵嘏","dynasty":"唐","verses":["九陌初晴处处春，不能回避看花尘。","由来得丧非吾事，本是钓鱼船上人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-62dbebd9-bd38-42e0-9747-1c8ac17f9eb9","tags":[]},{"id":"poem-6dd9325c13a990b10be27934","title":"玉楼春·东城渐觉风光好","author":"宋祁","dynasty":"宋","verses":["东城渐觉风光好。","皱波纹迎客棹。","绿杨烟外晓寒轻，红杏枝头春意闹。","浮生长恨欢娱少。","肯爱千金轻一笑。","为君持酒劝斜阳，且向花间留晚照。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-168","tags":["宋词三百首"]},{"id":"poem-6ddd285b3ea79d6cd7a09f13","title":"宣城北楼昔从顺阳公会于此","author":"鲍溶","dynasty":"唐","verses":["诗楼郡城北，窗牖敬亭山。","几步尘埃隔，终朝世界闲。","凭师看粉壁，名姓在其间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3d0e4cd4-51ef-4292-ad62-647d8205615f","tags":[]},{"id":"poem-6de5562c512bd64a0e530d00","title":"送韩愈从军","author":"孟郊","dynasty":"唐","verses":["志士感恩起，变衣非变性。","亲宾改旧观，僮仆生新敬。","坐作群书吟，行为孤剑咏。","始知出处心，不失平生正。","凄凄天地秋，凛凛军马令。","驿尘时一飞，物色极四静。","王师既不战，庙略在无竞。","王粲有所依，元瑜初应命。","一章喻檄明，百万心气定。","今朝旌鼓前，笑别丈夫盛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-37972b94-000b-468a-9075-dbf997309066","tags":[]},{"id":"poem-6de877fe5ab017bd3dc267da","title":"题祖山人池上怪石","author":"张碧","dynasty":"唐","verses":["寒姿数片奇突兀，曾作秋江秋水骨。","先生应是厌风云，著向江边塞龙窟。","我来池上倾酒尊，半酣书破青烟痕。","参差翠缕摆不落，笔头惊怪黏秋云。","我闻吴中项容水墨有高价，邀得将来倚松下。","铺却双缯直道难，掉首空归不成画。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9ff7a464-23c9-406b-b0ee-8c59bc0f3183","tags":[]},{"id":"poem-6df20057ecb0756e24b4082e","title":"浣溪沙·万里阴山万里沙","author":"纳兰性德","dynasty":"清","verses":["万里阴山万里沙。","谁将绿鬓斗霜华。","年来强半在天涯。","魂梦不离金屈戌，画图亲展玉鸦叉。","生怜瘦减一分花。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-42","tags":[]},{"id":"poem-6df52fabfc4a8935d1b217bd","title":"诗一首","author":"张载","dynasty":"宋","verses":["学易穷源未到时，便将虚寂眇心思。","宛如童子攻词赋，用即无差问不知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-c45127a7-24a9-403d-9485-cec04d06ba5a","tags":[]},{"id":"poem-6dfad5ed004ff985df88f12a","title":"效古","author":"澹交","dynasty":"唐","verses":["荣辱又荣辱，一何翻与覆。","人生百岁中，孰肯死前足。","玄鬓忽如丝，青丛不再绿。","自古争名徒，黄金是谁禄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-08921503-b709-494b-add8-12bafedf141c","tags":[]},{"id":"poem-6dfde240f48ef51c4b6a3654","title":"八哀诗 赠司空王公思礼","author":"杜甫","dynasty":"唐","verses":["司空出东夷，童稚刷劲翮。","追随燕蓟儿，颖锐物不隔。","服事哥舒翰，意无流沙碛。","未甚拔行间，犬戎大充斥。","短小精悍姿，屹然强寇敌。","贯穿百万众，出入由咫尺。","马鞍悬将首，甲外控鸣镝。","洗劒青海水，刻铭天山石。","九曲非外蕃，其王转深壁。","飞兔不近驾，鸷鸟资远击。","晓达兵家流，饱闻春秋癖。","胷襟日沈静，肃肃自有适。","潼关初溃散，万乘犹辟易。","偏裨无所施，元帅见手格。","太子入朔方，至尊狩梁益。","胡马缠伊洛，中原气甚逆。","肃宗登宝位，塞望势敦迫。","公时徒步至，请罪将厚责。","际会清河公，间道传玉册天王拜跪毕，谠议果冰释。","翠华卷飞雪，熊虎亘阡陌。","屯兵凤皇山，帐殿泾渭辟。","金成贼咽喉诏镇雄所搤。","禁暴清无双，爽气春淅沥。","巷有从公歌，野多青青麦。","及夫哭庙后，复领太原役恐惧禄位高，怅望王土窄。","不得见清时，呜呼就窀穸。","永系五湖舟，悲甚田横客。","千秋汾晋间，事与云水白。","昔观文苑传，岂述廉蔺绩。","嗟嗟邓大夫，士卒终倒戟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-40c8fa66-2802-43df-ada6-1bd286cb49db","tags":[]},{"id":"poem-6e05ddf7c91d6bcaba507497","title":"送严明府入关谒黎京兆","author":"皎然","dynasty":"唐","verses":["春日异秋风，何为怨别同。","潮回芳渚没，花落昼山空。","旅候闻嘶马，残阳望断鸿。","应思右内史，相见直城中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-af7c624d-780d-47a0-8eb0-0449c042c261","tags":[]},{"id":"poem-6e0f3624c1cce6be126fb685","title":"西江月·对镜不须强灭","author":"张伯端","dynasty":"宋","verses":["对镜不须强灭，假名权立菩提。","色空明暗本来齐。","真妄体分两种。","悟则便名静土，更无天竺曹溪。","谁言极乐在天西。","了则弥陀出世。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-987","tags":[]},{"id":"poem-6e11f4257bc22c5f9f4782ed","title":"送蔡十二之海上","author":"高适","dynasty":"唐","verses":["黯然何所为，相对但悲酸。","季弟念离别，贤兄救急难。","河流冰处尽，海路雪中寒。","尚有南飞雁，知君不忍看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-a98af493-3392-4ac3-b648-cb48118bff10","tags":[]},{"id":"poem-6e232f89d595fd75368bcc82","title":"遐方怨·欹角枕","author":"纳兰性德","dynasty":"清","verses":["欹角枕，掩红窗。","梦到江南，伊家博山沉水香。","湔裙归晚坐思量。","轻烟笼浅黛，月茫茫。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-204","tags":[]},{"id":"poem-6e236f1bc9f5d270d5622974","title":"久憾缧绁之作","author":"佚名","dynasty":"唐","verses":["一从命驾赴戎乡，几度躬先亘法梁。","吐纳共钦澎湃注，纵（原作「踪」）横竞揖慧风飏。","今时有恨同兰艾，即日无辜比冶长。","黠虏莫能分玉石，终朝谁念泪沾裳。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-69c943a6-a8e9-47ae-8fd8-86d88637ee34","tags":[]},{"id":"poem-6e3e670f26146606cba2f108","title":"挽朱宜人","author":"王柏","dynasty":"宋","verses":["蜀峰飞来不记年，嶪峨崒嵂青绵联。","康湖演漾吞万壑，风雷日夜喷飞泉。","水西葱鬰气方壮，水南重得黄牛眠。","深山大泽绝异处，造物冥锢难轻捐。","龙翔凤舞萃英淑，岂非天授夫人贤。","彩云落月相珪璧，山花庭草摇香钿。","虎羊甲士俨成列，万松磨飐生苍烟。","夫君笔力扛九鼎，亲著幽德熏兰荃。","应有山灵乘赤豹，千年呵护青瑶镌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-98f2148b-e8cb-4f31-a81f-ceb13550a3af","tags":[]},{"id":"poem-6e3f98038c01ed3ea353ac5b","title":"齐天乐·庾郎先自吟愁赋","author":"姜夔","dynasty":"宋","verses":["庾郎先自吟愁赋。","凄凄更闻私语。","露湿铜铺，苔侵石井，都是曾听伊处。","哀音似诉。","正思妇无眠，起寻机杼。","曲曲屏山，夜凉独自甚情绪。","西窗又吹暗雨。","为谁频断续，相和砧杵。","候馆迎秋，离宫吊月，别有伤心无数。","豳诗漫与。","笑篱落呼灯，世间儿女。","写入琴丝，一声声更苦。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-127","tags":["宋词三百首"]},{"id":"poem-6e45f3a5ed4c24bc379a1c6e","title":"外弟信臣总干西归驻舟沙岸得半月之款于其行口占道别","author":"张栻","dynasty":"宋","verses":["外家源流远，文物被诸孙。","嗟我数年来，颇识佳弟昆。","酥酪本同味，兰芷非殊根。","竞爽有如此，知当大其门。","信也来过我，气貌清而温。","方忻驻足地，中有静者存。","皎然明月光，岂复受浊浑。","埙箎迭和时，此理试共论。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-4bf91893-d53d-44d7-a533-da79fdd619d4","tags":[]},{"id":"poem-6e4677042d190e64550b7669","title":"圣恩顾问独游月磴阁直书其事应制","author":"广宣","dynasty":"唐","verses":["禅居河畔无多地，来往寻春物正华。","磴道上盘千亩竹，栏干低压万人家。","簷前施饭来飞鸟，林下行香踏落花。","自解刹那知佛性，不劳更喻几尘沙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f8312d3c-714f-429a-9a7a-c915224748de","tags":[]},{"id":"poem-6e4d2bbf1eef888091f40d95","title":"蝶恋花·门外沧洲山色近","author":"张镃","dynasty":"宋","verses":["门外沧洲山色近。","鸥鹭双双，恼乱行云影。","翠拥高筠阴满径。","帘垂尽日林堂静。","明月飞来烟欲暝。","水面天心，两个黄金镜。","慢飐轻摇风不定。","渔歌欸乃谁同听。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-357","tags":[]},{"id":"poem-6e4ec70b3df263dd3cebae42","title":"鹤冲天·梅雨霁","author":"周邦彦","dynasty":"宋","verses":["梅雨霁，暑风和。","高柳乱蝉多。","小园台榭远池波。","鱼戏动新荷。","薄纱厨，轻羽扇。","枕冷簟凉深院。","此时情绪此时天。","无事小神仙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-527","tags":[]},{"id":"poem-6e5174d5391120aa478912cc","title":"张丞见和次韵答之  其五","author":"陈造","dynasty":"宋","verses":["男儿鼎珍食，富贵倚稽古。","不然东山车，稳载十眉女。","可怜强项令，俗尘塞肠腑。","端如溧阳尉，老诉食荠苦。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-21121df0-d38f-4989-99c9-c43639e1b556","tags":[]},{"id":"poem-6e5460e569063dc893dfa55f","title":"张芬见访郊居作","author":"皇甫曾","dynasty":"唐","verses":["林中雨散早凉生，已有迎秋促织声。","三径荒芜羞对客，十年衰老愧称兄。","愁心自惜江蓠晚，世事方看木槿荣。","君若罢官携手日，寻山莫算白云程。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-707975d7-671c-4727-9168-3c6103cbdb20","tags":[]},{"id":"poem-6e547eb29e84eef8359b4683","title":"罢都统守镇滑州作","author":"王铎","dynasty":"唐","verses":["用军何事敢迁延，恩重才轻分使然。","黜诏已闻来阙下，檄书犹未遍军前。","腰间尽解苏秦印，波上虚迎范蠡船。","正会星辰扶北极，却驱戈甲镇南燕。","三尘上相逢明主，九合诸侯媿昔贤。","看却中兴扶大业，杀身无路好归田。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b96c0fe1-5315-4eae-9b61-3465e28ac073","tags":[]},{"id":"poem-6e560a29e54f9a39c4b55aef","title":"春秋战国门 庄辛","author":"周昙","dynasty":"唐","verses":["庄辛正谏谓妖词，兵及鄢陵始悔思。","见兔必能知顾犬，亡羊补栈未为迟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2521ab0b-cd2a-4a41-8b3b-d5c157729d83","tags":[]},{"id":"poem-6e5cd8e086c8e02f1bd45b94","title":"浣溪沙·粉上依稀有泪痕","author":"薛昭蕴","dynasty":"五代","verses":["粉上依稀有泪痕，郡庭花落欲黄昏，远情深恨与谁论。","记得去年寒食日，延秋门外卓金轮，日斜人散暗消魂。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-28","tags":[]},{"id":"poem-6e65004f073715f999d452b1","title":"寻山僧真胜上人不遇","author":"栖白","dynasty":"唐","verses":["松下禅栖所，苔滋径莫分。","青山春暮见，流水夜深闻。","不坐看心石，应随出定云。","猨猱非可问，岩谷自空曛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-48e2260b-6d78-4713-bf1b-2df974a97f80","tags":[]},{"id":"poem-6e6522141b3b08031cb909a1","title":"读离骚经","author":"贯休","dynasty":"唐","verses":["湘江滨，湘江滨，兰红芷白波如银，终须一去呼湘君。","问湘神，云中君，不知何以交灵均。","我恐湘江之鱼兮，死后尽为人。","曾食灵均之肉兮，个个为忠臣。","又想灵均之骨兮终不曲，千年波底色如玉。","谁能入水少取得，香沐函题贡上国。","贡上国，即全胜和璞悬瓈，垂棘结绿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2fa627ae-9d13-495c-a5f5-82822db1d81c","tags":[]},{"id":"poem-6e6a18f59cc523d9ca83ca51","title":"琮师送至城月驿戏成两绝句以答其意  其一","author":"李纲","dynasty":"宋","verses":["衲子来参去不辞，何劳飞锡远相追。","赠师银布牢收取，便是金襕付嘱时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-7f1dfb9e-ca3a-4c79-b5ca-dcdecc1dcae5","tags":[]},{"id":"poem-6e738ce028081f9e58356c74","title":"妾薄命","author":"李端","dynasty":"唐","verses":["自从君弃妾，憔悴不羞人。","唯余坏粉泪，未免映衫匀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9816ff60-fc81-4291-8d05-cad5e5541933","tags":[]},{"id":"poem-6e80e316d5f5eda4af476827","title":"闲田","author":"释了惠","dynasty":"宋","verses":["秦不耕兮汉不耘，镢头边事杳无闻。","年来也有秋成望，三合清风半合云。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-9964c3e7-aea3-48c2-b915-dc9bddc89805","tags":[]},{"id":"poem-6e864801e4d7de3dafbd68d9","title":"自昌谷到洛后门","author":"李贺","dynasty":"唐","verses":["九月大野白，苍芩竦秋门。","寒凉十月末，露霰蒙晓昏。","澹色结昼天，心事填空云。","道上千里风，野竹蛇涎痕。","石涧涷波声，鸡叫清寒晨。","强行到东舍，解马投旧邻。","东家名廖者，乡曲传姓辛。","杖头非饮酒，吾请造其人。","始欲南去楚，又将西适秦。","襄王与武帝，各自留青春。","闻道兰台上，宋玉无归魂。","缃缥两行字，蛰虫蠹秋芸。","为探秦台意，岂命余负薪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-285ac776-5a32-4366-af69-92136732c1b5","tags":[]},{"id":"poem-6e87a22eb206e386e7a4cf1f","title":"北至太原","author":"李益","dynasty":"唐","verses":["炎祚昔昏替，皇基此郁盘。","玄命久已集，抚运良乃艰。","南阨羊肠险，北走雁门寒。","始于一戎定，垂此亿世安。","唐风本忧思，王业寔艰难。","中历虽横溃，天纪未可干。","圣明所兴国，灵岳固不殚。","咄咄薄游客，斯言殊不刊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-8500c255-d23f-45d9-9e39-740d3db74207","tags":[]},{"id":"poem-6e92118c60a430461f998cf0","title":"十六","author":"王梵志","dynasty":"唐","verses":["耶娘绝年迈，不得离傍边。","晓夜专看待，（「看待」，伯三六五六卷作「看侍」。","）仍须省睡眠。","（「省睡眠」，斯三三九三卷作「更省眠」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ee1014b0-3efa-464c-9bc6-c5ac01f395e3","tags":[]},{"id":"poem-6ea1c9af2b701212f6df8a7e","title":"偈","author":"启柔","dynasty":"唐","verses":["妙哉三下板，诸德（《五灯会元》作「知识」）尽来参。","既善分时节，吾今不再三。","（《景德传灯录》卷二二、《五灯会元》卷十五。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-08e4df9e-d4ca-4e2d-b959-5ddbff95c2f1","tags":[]},{"id":"poem-6eac75eba4beeace5edff18d","title":"余尸巾山苦诛求而去钵无舂粮寓公范公伟质衣以赆西笑曰乱邦不居行矣","author":"释居简","dynasty":"宋","verses":["廉士难于俗吏并，质衣犹及送僧行。","惠惟适用偏多感，施及无求益见情。","弱羽敢辞三足妬，伏雌常与九包争。","故家逸韵难谐俗，共作台州一段清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-0253dd43-7cd3-4d6c-9172-8d53083997c0","tags":[]},{"id":"poem-6eaf23d5175315067d2ec08c","title":"蒋叔行挽辞  其一","author":"王柏","dynasty":"宋","verses":["万山蟠兮有宅一区，吁嗟吉士兮心古而色愉。","平生激烈兮谈忠义之事，求师教子兮必有道之儒。","流德谊兮鼎鼎，浸策足兮功名之途。","引壶觞兮自适，玩日月之双车。","有淑兮尔配，丝枲兮劬劬。","指期颐兮二竖立病，既偕老兮亦相继而长徂。","望双旌兮有恸，酹一束兮生刍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-3efda50b-05d4-4440-93b7-3a098b8df407","tags":[]},{"id":"poem-6eb33d2ed2a1654c5d9018ba","title":"草堂","author":"杜甫","dynasty":"唐","verses":["昔我去草堂，蛮夷塞成都。","今我归草堂，成都适无虞。","请陈初乱时，反复乃须臾。","大将赴朝廷，群小起异图。","中宵斩白马，盟歃气已麤。","西取邛南兵，北断劒阁隅。","布衣数十人，亦拥专城居。","其势不两大，始闻蕃汉殊。","西卒却倒戈，贼臣互相诛。","焉知肘腋祸，自及枭獍徒。","义士皆痛愤，纪纲乱相逾。","一国实三公，万人欲为鱼。","唱和作威福，孰肯辨无辜。","眼前列杻械，背后吹笙竽。","谈笑行杀戮，溅血满长衢。","到今用钺地，风雨闻号呼。","鬼妾与鬼马，色悲充尔娱。","国家法令在，此又足惊吁。","贱子且奔走，三年望东吴。","弧矢暗江海，难为游五湖。","不忍竟舍此，复来薙榛芜。","入门四松在，步屧万竹疎。","旧犬喜我归，低徊入衣裾。","邻舍喜我归，酤酒携胡芦。","大官喜我来，遣骑问所须。","城郭喜我来，宾客隘邨墟。","天下尚未宁，健儿胜腐儒。","飘飖风尘际，何地置老夫。","于时见疣赘，骨髓幸未枯。","饮啄媿残生，食薇不敢余。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-32bfdf4c-b903-4517-8f91-d25331134e12","tags":["抒情","国家","感慨"]},{"id":"poem-6ec238a31f902f086f8e59e6","title":"同李九士曹观壁画云作","author":"高适","dynasty":"唐","verses":["始知帝乡客，能画苍梧云。","秋天万里一片色，只疑飞尽犹氛氲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-101844bd-db52-4b7b-a097-c45162545c77","tags":[]},{"id":"poem-6ec6138c924b5f20cd88123b","title":"生查子·近似月当怀","author":"向子𬤇","dynasty":"宋","verses":["近似月当怀，远似花藏雾。","好是月明时，同醉花深处。","看花不自持，对月空相顾。","愿学月频圆，莫作花飞去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-777","tags":[]},{"id":"poem-6ec6f7cc0083695607cf09d9","title":"孝顺歌","author":"萧德祥《小孙屠》","dynasty":"元","verses":["我哥不是，怨自谁？痴迷那得人似你。","兄弟好言语，佯佯总不理，如风过耳。","它是风尘，烟花泼妓。","你娶为妻，不思量有今日。","(生)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8660","tags":[]},{"id":"poem-6eccbe98a3ecf78d3536a3e5","title":"海南黎人作过据临臯县惊刼傍近因小留海康十一月望闻官军破贼二十日戒行戏作两绝句  其一","author":"李纲","dynasty":"宋","verses":["海上群黎亦弄兵，征车数月旅山城。","稽留谪命兢惶甚，正坐绯巾惩沸羮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-b00e725c-7426-4830-ad50-72b2eb32e20d","tags":[]},{"id":"poem-6ed2a5ec5a0de3fea8e7fac2","title":"渊圣皇帝题十八学士颂","author":"李纲","dynasty":"宋","verses":["英英策府，十八学士。","森如骥𫘧，才德兼备。","太宗御之，六辔耳耳。","嘶风𥬞云，一日千里。","丹青之妙，写于缣素。","千载风流，遇之旦暮。","於穆渊圣，天纵多能。","游戏翰墨，识其姓名。","人物图绘，及兹宸藻。","是为三绝，万世之宝。","沙漠苦寒，翠华未还。","伤心北顾，喟其涕澘。","安得杰才，如彼诸子。","扶翊中微，国势振起。","岂无赵卒，为御以归。","老臣衰疾，跂而望之。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a115e564-5754-42f7-9896-cc5e66122e29","tags":[]},{"id":"poem-6ed67513198b226839da78cb","title":"昔年二首  其二","author":"赵文","dynasty":"宋","verses":["少年如此已成枯，我亦重来白鬓须。","正使冥冥有知识，不知还认阿兄无。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-c5b7a448-84bf-478e-b710-d32d8be6eb76","tags":[]},{"id":"poem-6ed7f69800ae60fa7fde4a5d","title":"虞美人·去年雪满长安树","author":"向子𬤇","dynasty":"宋","verses":["去年雪满长安树。","望断扬州路。","今年看雪在扬州。","人在蓬莱深处、若为愁。","而今不恨伊相误。","自恨来何暮。","平山堂下旧嬉游。","只有舞春杨柳、似风流。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-759","tags":[]},{"id":"poem-6edbc1228022157e1a54645a","title":"桃夭","author":"佚名","dynasty":"先秦","verses":["桃之夭夭，灼灼其华。之子于归，宜其室家。","桃之夭夭，有蕡其实。之子于归，宜其家室。","桃之夭夭，其叶蓁蓁。之子于归，宜其家人。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-5","tags":[]},{"id":"poem-6edc0a5af3611ad7f3e6cdf1","title":"送王炎弼赴山阳守以兵卫森画戟宴寝凝清香为韵十首  其九","author":"曾协","dynasty":"宋","verses":["复旦风云合，丹心日月明。","江神回朗照，霁色向来清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-74b6773a-b63a-4608-b825-5a7aaa6ce42b","tags":[]},{"id":"poem-6ee14f420d588f7c12eddcaf","title":"魏将军歌","author":"杜甫","dynasty":"唐","verses":["将军昔著从事衫，铁马驰突重两衔。","披坚执锐略西极，昆仑月窟东崭岩。","君门羽林万猛士，恶若哮虎子所监。","五年起家列霜戟，一日过海收风帆。","平生流辈徒蠢蠢，长安少年气欲尽。","魏侯骨耸精爽紧，华岳峰尖见秋隼。","星躔宝校金盘陀，夜骑天驷超天河。","欃枪荧惑不敢动，翠蕤云旓相荡摩。","吾为子起歌都护，酒阑插劒肝胆露。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-67761270-0287-499c-b702-123d49c2786d","tags":[]},{"id":"poem-6ee94761bfa3bcfca01f7ef5","title":"京中即事","author":"王镃","dynasty":"宋","verses":["笙歌无处不繁华，春在鶑鶑燕燕家。","谁看少年骑马过，娇红微露隔帘花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e526e07a-cb67-45ea-b4c7-39418750ca8e","tags":[]},{"id":"poem-6eee50dae7ab081b200383cf","title":"玉楼春·泥银四壁盘蜗篆","author":"毛滂","dynasty":"宋","verses":["泥银四壁盘蜗篆。","明月一庭秋满院。","不知陶菊总开无，但见杜苔新雨遍。","去年醉倒云为簟。","未尽百壶惊日短。","小云今夜伴牢愁，好在凤凰春未晚。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-766","tags":[]},{"id":"poem-6ef231001d56cbcfa28734c1","title":"菊花新·怎奈花残又莺老","author":"杜安世","dynasty":"宋","verses":["怎奈花残又莺老。","槛里青梅数枝小。","新荷长池沼。","当晴昼、燕子声闹。","亭栏花绽颜色好。","风雨催催、等闲开了。","酒醒暗思量，无个事、甚刚烦恼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-937","tags":[]},{"id":"poem-6efd73b6efe8b54b3fd43d93","title":"和张文裕初寒十首  其八","author":"司马光","dynasty":"宋","verses":["何处初寒好，初寒肃政台。","官闲免簿领，门静少尘埃。","天借风霜气，人无鹰隼猜。","庭荒余老柏，尚有夕乌来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-5d654381-68c4-462a-94d6-a644bd98d557","tags":[]},{"id":"poem-6f09bddddb3cbd18929c6b30","title":"送洁老归碧云新居","author":"释居简","dynasty":"宋","verses":["小小如巢便称怀，隣无百万买洪崖。","炊云子熟呼仙饷，借雪精游与俗乖。","禅谬分灯传口耳，耕宁合耦外形骸。","田中大义休提掇，定与诸方打不谐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-1f8b5814-a27e-4f84-a0aa-53483dd2a493","tags":[]},{"id":"poem-6f0a5db63e2b026776107a71","title":"山中冬思二首 二","author":"鲍溶","dynasty":"唐","verses":["雪壮冰亦坚，冻涧如平地。","幽人毛褐煖，笑就糟床醉。","唤人空谷应，开火寒猨至。","拾薪煮秋栗，看鼎书古字。","忽忆南涧游，衣巾多云气。","露脚寻逸僧，咨量意中事。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fd3ccca7-b611-4b71-9ab8-6f8ce1ec6889","tags":[]},{"id":"poem-6f0c15c2d99669197ba7e80c","title":"遣兴五首 一","author":"杜甫","dynasty":"唐","verses":["天用莫如龙，有时系扶桑。","顿辔海徒涌，神人身更长。","性命苟不存，英雄徒自强。","吞声勿复道，真宰意茫茫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7beb1d4a-e1c9-4fc5-9ba1-82f46a724480","tags":[]},{"id":"poem-6f0c4c33d60e3789df3576bb","title":"早春霁后发头陀寺寄院中","author":"李涉","dynasty":"唐","verses":["红楼金刹倚晴冈，雨雪初收望汉阳。","草檄可中能有暇，迎春一醉也无妨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-a3512f84-94d1-4088-87e2-c05dbb8ca17b","tags":[]},{"id":"poem-6f0cf5c14a36167a6178584c","title":"寄贾岛","author":"马戴","dynasty":"唐","verses":["海上不同来，关中俱久住。","寻思别山日，老尽经行树。","志业人未闻，时光鸟空度。","风悲汉苑秋，雨滴秦城暮。","佩玉与锵金，非亲亦非故。","朱颜枉自毁，明代空相遇。","岁晏各能归，心知旧歧路。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2534da75-79ec-4db7-aac5-8d53c77b034c","tags":[]},{"id":"poem-6f0ef8dba169ed3e25686b68","title":"送曹郎中南归时南中用军","author":"李洞","dynasty":"唐","verses":["桂水净和天，南归似谪仙。","系绦轻象笏，买布接蛮船。","海气蒸鼙软，江风激箭偏。","罢郎吟乱里，帝远岂知贤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-d9e89292-9e3a-485e-bb3a-8fd48ffe253f","tags":[]},{"id":"poem-6f22f235cd16aa2862b72b95","title":"黄神谷纪事","author":"马戴","dynasty":"唐","verses":["霹雳振秋岳，折松横洞门。","云龙忽变化，但觉玉潭昏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-51479f73-6ab6-4dc2-8390-7133e7f759ce","tags":[]},{"id":"poem-6f29219d494cffd61e9d8f2d","title":"菩萨蛮·惜春春去惊新燠","author":"纳兰性德","dynasty":"清","verses":["惜春春去惊新燠，粉融轻汗红绵扑。","妆罢只思眠，江南四月天。","绿阴帘半揭，此景清幽绝。","行度竹林风，单衫杏子红。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-185","tags":[]},{"id":"poem-6f378ae0b877495c96b327e3","title":"即景","author":"朱淑贞","dynasty":"宋","verses":["竹摇清影罩幽窗，两两时禽噪夕阳。","谢却海棠飞尽絮，困人天气日初长。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-即景","tags":[]},{"id":"poem-6f3b8dc665ac8a323c3ecef3","title":"送客之蜀","author":"杨凌","dynasty":"唐","verses":["西蜀三千里，巴南水一方。","晓云天际断，夜月峡中长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e82dfaab-abac-499f-a438-8258a87ac7ce","tags":[]},{"id":"poem-6f3e4e036cfb4266f6733ed3","title":"缁衣","author":"佚名","dynasty":"先秦","verses":["缁衣之宜兮，敝予又改为兮。适子之馆兮。还予授子之粲兮。","缁衣之好兮，敝予又改造兮。适子之馆兮，还予授子之粲兮。","缁衣之席兮，敝予又改作兮。适子之馆兮，还予授子之粲兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-74","tags":[]},{"id":"poem-6f3ee70658fbd6da70c98dc7","title":"明妃曲","author":"陈造","dynasty":"宋","verses":["汉宫第一人，只合侍天子。","四弦春风手，可用入胡耳。","天生国艳或为累，金赂画工宁不耻。","玉颜初作万里行，朔风黧面边尘昏。","路人私语泪栖睫，况妾去国怀君恩。","穹庐渐耐胡天冷，政复难忘心耿耿。","夜深拜月望长安，顾叹当时未央影。","胡雏酌酒单于舞，铭肺千年朝汉主。","传闻上谷与萧关，自顷耕桑皆乐土。","向来屯饷仍缯絮，庙算年年关圣虑。","但令黄屋不宵衣，埋骨龙荒妾其所。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-4d5e732f-0e51-4145-8e95-a9228d50a8a9","tags":[]},{"id":"poem-6f416d2857bdd3d379e327e8","title":"蒹葭","author":"佚名","dynasty":"先秦","verses":["蒹葭苍苍，白露为霜。所谓伊人，在水一方。溯洄从之，道阻且长。溯游从之，宛在水中央。","蒹葭萋萋，白露未晞。所谓伊人，在水之湄。溯洄从之，道阻且跻。溯游从之，宛在水中坻。","蒹葭采采，白露未已。所谓伊人，在水之涘。溯洄从之，道阻且右。溯游从之，宛在水中沚。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-128","tags":[]},{"id":"poem-6f466f1584245f3aa3f97caf","title":"送桂阳孝廉","author":"高适","dynasty":"唐","verses":["桂阳年少西入秦，数经甲科犹白身。","即今江海一归客，他日云霄万里人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-54d11196-da71-464b-9058-241799947513","tags":[]},{"id":"poem-6f4c1f5aa37f5c8e1954d2f9","title":"满庭芳·腊雪方凝","author":"葛立方","dynasty":"宋","verses":["腊雪方凝，春曦俄漏，画堂小秩芳筵。","玉台仙蕊，帘外幂瑶烟。","莫话青山万树，聊须对、一段孤妍。","杯行处，香参鼻观，百濯未为贤。","吾庐，何处好，绣香竹畔，偶桂溪边。","且为渠珍重，满泛金船。","已拚春酲一枕，如今且、醉倒花前。","花飞后，欢呼一笑，又是说明年。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-509","tags":[]},{"id":"poem-6f4de0dbe59d16755fa6699c","title":"雨中怨秋","author":"杨凭","dynasty":"唐","verses":["辞家远客怆秋风，千里寒云与断蓬。","日暮隔山投古寺，钟声何处雨蒙蒙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c646227d-122c-493c-b1fb-410397eb65f7","tags":[]},{"id":"poem-6f5192c93a6a0590a4daec08","title":"长沙过贾谊宅","author":"刘长卿","dynasty":"唐","verses":["三年谪宦此栖迟，万古惟留楚客悲。","秋草独寻人去后，寒林空见日斜时。","汉文有道恩犹薄，湘水无情吊岂知。","寂寂江山摇落处，怜君何事到天涯。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8cefa67f-2b9a-4e13-8158-4d38cbfb331b","tags":["唐诗三百首","迁谪","生活","怀古","七言律诗"]},{"id":"poem-6f53356be58cef14056cec48","title":"清庙","author":"佚名","dynasty":"先秦","verses":["于穆清庙，肃雍显相。济济多士，秉文之德。对越在天，骏奔走在庙。不显不承，无射于人斯。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-265","tags":[]},{"id":"poem-6f53e30372d7d171399ad58e","title":"跋王介甫游钟山图","author":"张栻","dynasty":"宋","verses":["林影溪光静自如，萧疎短鬓独骑馿。","可能胸次都无事，拟向山中更著书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-32a792ef-452b-4ad9-b969-b8d9d72f3e5f","tags":[]},{"id":"poem-6f689c2ad67d867631955aa7","title":"寄赤松舒道士二首 二","author":"贯休","dynasty":"唐","verses":["余亦如君也，诗魔不敢魔。","一餐兼午睡，万事不如他。","雨阵冲溪月，蛛丝罥砌莎。","近知山果熟，还拟寄来么。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-def6beb6-726d-417c-a6d9-2ed535e096f4","tags":[]},{"id":"poem-6f76b9a204780ca8d7ef5dd3","title":"金谷园","author":"杜牧","dynasty":"唐","verses":["繁华事散逐香尘，流水无情草自春。","日暮东风怨啼鸟，落花犹似堕楼人。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-80159919-0b66-4956-a563-ef9bcf6a05c0","tags":["唐诗三百首","七言绝句","怀古"]},{"id":"poem-6f78b03d587e012966d2015d","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["一旦分离掌上珠，我这老景凭谁？忍将父母饥寒死，博换得孩儿名利归。","你纵然衣锦归故里，补不得你名行亏。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4941","tags":[]},{"id":"poem-6f78be7fa60b46a53782bec2","title":"漫书五首 三","author":"司空图","dynasty":"唐","verses":["海上昔闻麋爱鹤，山中今日鹿憎龟。","爱憎止竟须关分，莫把微才望所知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ab3be046-ac42-425a-8e9f-def1a53542b3","tags":[]},{"id":"poem-6f7e833cb35808ec98beb602","title":"经涢川馆寄使府群公","author":"李涉","dynasty":"唐","verses":["涢川水竹十家余，渔艇蓬门对岸居。","大胜尘中走鞍马，与他军府判文书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-11804387-bd3a-45ad-87fc-186e892ef378","tags":[]},{"id":"poem-6f890e925576959789e13c8a","title":"姑熟杂咏 丹阳湖","author":"李赤","dynasty":"唐","verses":["湖与元气通，风波浩难止。","天外贾客归，云间片帆起。","龟游莲叶上，鸟宿芦花里。","少女棹舟归，歌声逐流水。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1b2fa983-01ec-4aed-a9f3-3a50bc295323","tags":[]},{"id":"poem-6f910df0bea0765c326900a0","title":"非所寄王都护姨夫","author":"佚名","dynasty":"唐","verses":["敦煌数度访来人，握手千回问懿亲。","蓬转已闻过海畔，莎居见说傍河津。","戎庭事事皆违意，虏口朝朝计苦辛。","缧绁傥逢恩降日，宿心言豁（原作「豁」）在他辰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3aee7aef-570f-45a7-b346-d1ff60cfb1eb","tags":[]},{"id":"poem-6f9d1c5a35b4cd44b25791f4","title":"新年作","author":"宋之问","dynasty":"唐","verses":["乡心新岁切，天畔独澘然。","老至居人下，春归在客先。","岭猨同旦暮，江柳共风烟。","已似长沙傅，从今又几年。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-368fc6bb-1636-419e-8ddb-cdc1dd07a1ca","tags":["唐诗三百首","五言律诗","春节","思乡"]},{"id":"poem-6fa768a08b12c13409c67ab2","title":"清平乐","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["夫妻两月，一旦成分别。","没主公婆甘旨缺，几度思量悲切。","家贫先自艰难，那更不遇丰年。","恁的千辛万苦，苍天也不相怜。","奴家自从儿夫出去，遭此饥荒；况兼公婆年老，朝不保夕。","教奴家独自，如何区处？婆婆日夜埋冤公公，当初不合教孩儿出去。","如今饥荒，教媳妇怎生区处。","公公又不伏善，只管在家煎妙。","免不得等公公婆婆出来，待奴家着些产道理，劝解则个。","(外上唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4991","tags":[]},{"id":"poem-6fa79c348521bec6e3666ea9","title":"曲江暮春雪霁","author":"曹松","dynasty":"唐","verses":["霁动江池色，春残一去游。","菰风生马足，槐雪滴人头。","北阙尘未起，南山青欲流。","如何多别地，却得醉汀洲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8be69b7d-175e-44f0-bd5a-7f1fe621029d","tags":[]},{"id":"poem-6fab5659339afcf30b7e8f77","title":"寄卫别驾","author":"李山甫","dynasty":"唐","verses":["晓屐归来岳寺深，尝思道侣会东林。","昏沈天竺看经眼，萧索净名老病心。","云盖数重横陇首，苔花千点遍松阴。","知君超达悟空旨，三径闲行抱素琴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3f4d7d31-3aba-4742-8b39-b2c3d406fd3a","tags":[]}];
